function AuthLangPill() {
  const cur = useZLang();
  const [open, setOpen] = useState(false);
  const [want, setWant] = useState(zlangWanted);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const off = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const key = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('pointerdown', off);
    document.addEventListener('keydown', key);
    return () => { document.removeEventListener('pointerdown', off); document.removeEventListener('keydown', key); };
  }, [open]);
  const on = want || cur;
  const shown = ZLANGS.find((l) => l.k === on) || ZLANGS[0];
  return (
    <div ref={ref} style={{ position: 'relative', marginLeft: 'auto', flexShrink: 0 }}>
      <button type="button" aria-label="Language" aria-haspopup="menu" aria-expanded={open} onClick={() => { hapticTap(); setOpen((v) => !v); }} className="zchat-press"
        style={{ height: 38, padding: '0 14px 0 11px', borderRadius: 19, border: `1.5px solid ${AUTH_C.line}`, background: '#FFFFFF', color: AUTH_C.ink, display: 'flex', alignItems: 'center', gap: 7, fontFamily: AUTH_FONT, fontSize: 14, fontWeight: 600, cursor: 'pointer' }}>
        <AuthGlobe size={17} />
        <span data-zuser="" lang={shown.k}>{shown.native}</span>
      </button>
      {open && (
        <div role="menu" className="zchat-fade" style={{ position: 'absolute', right: 0, top: 44, zIndex: 20, minWidth: 168, background: '#FFFFFF', borderRadius: 18, boxShadow: '0 12px 32px rgba(20,36,58,0.16)', border: `1px solid ${AUTH_C.line}`, padding: 6, boxSizing: 'border-box' }}>
          {ZLANGS.map((l) => (
            <button key={l.k} type="button" role="menuitemradio" aria-checked={on === l.k} lang={l.k} onClick={() => { hapticTap(); setWant(l.k); setOpen(false); setZLang(l.k); }}
              style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, minHeight: 44, padding: '0 12px', border: 'none', borderRadius: 12, background: on === l.k ? AUTH_C.field : 'transparent', color: AUTH_C.ink, fontFamily: AUTH_FONT, fontSize: 15, fontWeight: 600, cursor: 'pointer', textAlign: 'left' }}>
              <span data-zuser="">{l.native}</span>
              {on === l.k && <Check size={16} strokeWidth={2.6} />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

