function AppleButton({ onError, onBegin }) {
  const { theme } = useTheme();
  const [loading, setLoading] = useState(false);
  const providers = useAuthProviders();
  const click = async () => {
    if (loading) return;
    setLoading(true);
    if (onBegin) onBegin();
    try {
      const { error } = await supabase.auth.signInWithOAuth({ provider: 'apple', options: { redirectTo: window.location.origin } });
      if (error) {
        setLoading(false);
        const msg = String(error.message || '');
        if (onError) onError(/not enabled|unsupported provider|validation_failed/i.test(msg) ? 'Logging in with Apple is not switched on for ZChat yet. Use Google or email for now.' : friendlyError(error, "Couldn't log in with Apple. Try again."));
      }
    } catch {
      setLoading(false);
      if (onError) onError("Couldn't open Apple login. Try again.");
    }
  };
  if (!providers || !providers.apple) return null;
  return (
    <button type="button" onClick={click} disabled={loading} aria-label="Continue with Apple" className="zchat-press" style={socialBtnStyle(theme, loading)}>
      {loading ? <Spinner size={15} color={theme.ink} /> : (<><AppleLogo size={19} color={theme.ink} />Apple</>)}
    </button>
  );
}

