export const GOOGLE_CLIENT_ID = '103023880766-q4ok0uqj8pndf72vr3mrgg9r4sgnjhu9.apps.googleusercontent.com';

let googleScriptPromise = null;
export function loadGoogleIdentityScript() {
  if (googleScriptPromise) return googleScriptPromise;
  googleScriptPromise = new Promise((resolve, reject) => {
    if (window.google?.accounts?.id) { resolve(); return; }
    const existing = document.getElementById('google-identity-script');
    if (existing) { existing.addEventListener('load', () => resolve()); existing.addEventListener('error', reject); return; }
    const script = document.createElement('script');
    script.id = 'google-identity-script';
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error('load-failed'));
    document.head.appendChild(script);
  });
  return googleScriptPromise;
}

export async function sha256Hex(input) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, '0')).join('');
}

export function randomNonce() {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr).map((b) => b.toString(16).padStart(2, '0')).join('');
}

function GoogleButton({ onError, onBegin }) {
  const { theme } = useTheme();
  const [loading, setLoading] = useState(false);
  const handleClick = async () => {
    if (loading) return;
    setLoading(true);
    if (onBegin) onBegin();
    try {
      const rawNonce = randomNonce();
      const hashedNonce = await sha256Hex(rawNonce);
      await loadGoogleIdentityScript();
      if (!window.google?.accounts?.id) throw new Error('unavailable');
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        nonce: hashedNonce,
        use_fedcm_for_prompt: true,
        callback: async (response) => {
          setLoading(false);
          const { error } = await supabase.auth.signInWithIdToken({ provider: 'google', token: response.credential, nonce: rawNonce });
          if (error && onError) onError(friendlyError(error, "Couldn't log in with Google. Try again."));
        },
      });
      window.google.accounts.id.prompt((notification) => {
        if (notification.isNotDisplayed?.() || notification.isSkippedMoment?.()) {
          setLoading(false);
          supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: window.location.origin } });
        }
      });
    } catch {
      setLoading(false);
      if (onError) onError("Couldn't reach Google. Check your connection and try again.");
    }
  };
  return (
    <button type="button" onClick={handleClick} disabled={loading} aria-label="Continue with Google" className="zchat-press" style={socialBtnStyle(theme, loading)}>
      {loading ? <Spinner size={15} color={theme.ink} /> : (<><GoogleLogo size={18} />Google</>)}
    </button>
  );
}

