  useEffect(() => () => { if (onStageChange) onStageChange(null); }, []);
  useEffect(() => {
    if (initialStage !== 'username') return;
    (async () => {
      const { data } = await supabase.auth.getUser();
      const meta = data?.user?.user_metadata;
      if (meta?.full_name && !name) setName(meta.full_name);
      if (meta?.avatar_url && !avatarUrl) setAvatarUrl(meta.avatar_url);
    })();
  }, [initialStage]);
  const go = (s) => { setErr(''); setStage(s); };
  useEffect(() => { if (stage === 'email') shownAt.current = Date.now(); }, [stage]);
  const afterBirthday = initialStage === 'username' ? 'username' : 'email';
  const confirmBirthday = () => {
    const iso = birthIso(dob);
    if (!iso || !terms) return;
    const age = ageFromBirth(iso);
    if (age == null || age < 0 || age > 120) { setErr('Check the date and try again.'); return; }
    if (age < 13) { ageHoldSet(); go('young'); return; }
    regAgeSave({ dob: iso, at: new Date().toISOString() });
    go(afterBirthday);
  };
