    if (loading) return false;
    setLoading(true); setErr('');
    if (tempEmail(cleanEmail)) {
      setLoading(false);
      setErr(TEMP_MAIL_TEXT);
      return false;
    }
    if (await isBlockedHere(cleanEmail)) {
      setLoading(false);
      setErr(BLOCKED_MESSAGE);
      return false;
    }
    if (checkedFor.current !== cleanEmail.toLowerCase()) {
      const pre = await signupPrecheck({ email: cleanEmail, hp, t: Date.now() - shownAt.current, token: tsToken }, true);
      if (!pre.ok) { setLoading(false); setErr(pre.error); setTsToken(''); setTsReset((n) => n + 1); return false; }
      checkedFor.current = cleanEmail.toLowerCase();
    }
    const { error } = await registerWithEmail(cleanEmail);
    setLoading(false);
    if (error) { setErr(signupErrorText(error) || friendlyError(error, "Couldn't send the code. Try again.")); return false; }
