export const countryFlag = (code) => code.split('').map((c) => String.fromCodePoint(127397 + c.charCodeAt(0))).join('');

const DTF_CACHE = new Map();
function dtf(opts) {
  const k = JSON.stringify(opts);
  let f = DTF_CACHE.get(k);
  if (!f) {
    try { f = new Intl.DateTimeFormat(undefined, opts); } catch { f = new Intl.DateTimeFormat(); }
    DTF_CACHE.set(k, f);
  }
  return f;
}
const HM_FMT = { hour: 'numeric', minute: '2-digit' };
export function fmtHM(d) { try { return dtf(HM_FMT).format(d); } catch { return ''; } }
export function fmtDate(d, opts) { try { return dtf(opts).format(d); } catch { return ''; } }

function formatLastSeen(iso) {
  if (!iso) return null;
  const then = new Date(iso);
  const now = new Date();
  const time = fmtHM(then);
  const isToday = then.toDateString() === now.toDateString();
  const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
  const isYesterday = then.toDateString() === yesterday.toDateString();
  const diffMin = Math.round((now.getTime() - then.getTime()) / 60000);
  if (diffMin < 1) return 'Last seen just now';
  if (isToday) return `Last seen today at ${time}`;
  if (isYesterday) return `Last seen yesterday at ${time}`;
  const diffDay = Math.round(diffMin / 1440);
  if (diffDay < 7) return `Last seen ${diffDay} day${diffDay === 1 ? '' : 's'} ago`;
  return `Last seen ${fmtDate(then, { month: 'short', day: 'numeric' })}`;
}

function getSavedAccounts() {
  try { return JSON.parse(localStorage.getItem('zchat-accounts') || '[]'); } catch { return []; }
}
function saveAccountEntry(entry) {
  const list = getSavedAccounts().filter((a) => a.id !== entry.id);
  list.push(entry);
  try { localStorage.setItem('zchat-accounts', JSON.stringify(list)); } catch {}
}
function removeAccountEntry(id) {
  const list = getSavedAccounts().filter((a) => a.id !== id);
  try { localStorage.setItem('zchat-accounts', JSON.stringify(list)); } catch {}
}

export function botPicUrl() { return typeof window !== 'undefined' && window.location ? `${window.location.origin}/bot-avatar.jpg` : '/bot-avatar.jpg'; }
function botPic(p) { return p && p.is_bot && !(typeof p.avatar === 'string' && /^(https?:|zp:|blob:|data:)/.test(p.avatar)) ? { ...p, avatar: botPicUrl() } : p; }
export function sanitizeAvatar(profile, myId) {
  if (!profile) return profile;
  if (profile.is_bot) return botPic(profile);
  if (profile.hide_photo && profile.id !== myId) return { ...profile, avatar: '', avatar_anim: null };
  noteAvatarAnim(profile);
  return profile;
}
export function sanitizeAvatarList(list, myId) {
  return (list || []).map((p) => sanitizeAvatar(p, myId));
}

export const PROFILE_COLS = 'id, name, username, avatar, is_private, verified, custom_badge, avatar_frame, nameplate, pronouns, last_seen, created_at, is_bot, is_deleted, banned, read_receipts, status_text, status_emoji, status_until, away_on, away_text, avatar_cfg, song, visitors_on, ama_on, cover_url, interests, verified_until, name_style, profile_theme, followers, avatar_anim';
const PROFILE_SAVE_COLS = PROFILE_COLS.split(', ').filter((c) => c !== 'avatar' && c !== 'last_seen' && c !== 'avatar_anim').join(', ');
const AVATAR_ANIM_PATH = /^[0-9a-f-]{36}\/[A-Za-z0-9_-][A-Za-z0-9._-]{0,139}\.(mp4|webm)$/i;
const avatarAnimUrls = new Map();
export function avatarAnimSrc(v) {
  if (typeof v !== 'string' || !AVATAR_ANIM_PATH.test(v)) return null;
  if (!avatarAnimUrls.has(v)) {
    let u = null;
    try { u = supabase.storage.from('chat-media').getPublicUrl(v).data.publicUrl || null; } catch {}
    avatarAnimUrls.set(v, u);
  }
  return avatarAnimUrls.get(v);
}
const avatarAnimByPic = new Map();
const avatarAnimWait = new Map();
let avatarAnimSaveT = 0;
try {
  const raw = typeof localStorage !== 'undefined' ? JSON.parse(localStorage.getItem('zchat-avatar-anims') || '[]') : [];
  if (Array.isArray(raw)) raw.slice(-300).forEach((x) => { if (Array.isArray(x) && typeof x[0] === 'string' && typeof x[1] === 'string') avatarAnimByPic.set(x[0], x[1]); });
} catch {}
function animFixPending(path) {
  if (!path || typeof path !== 'string' || typeof VideoEncoder === 'undefined') return false;
  try { const m = JSON.parse(localStorage.getItem('zchat-anim-fixed') || '{}'); const v = m && m[path]; return !(v === 'ok' || (typeof v === 'number' && v >= 2)); } catch { return false; }
}
export function noteAvatarAnim(p) {
  if (!p || typeof p !== 'object' || typeof p.avatar !== 'string' || p.avatar.indexOf('http') !== 0 || !Object.prototype.hasOwnProperty.call(p, 'avatar_anim')) return;
  const next = typeof p.avatar_anim === 'string' && AVATAR_ANIM_PATH.test(p.avatar_anim) ? p.avatar_anim : null;
  const prev = avatarAnimByPic.get(p.avatar) || null;
  if (prev === next) return;
  if (next) avatarAnimByPic.set(p.avatar, next); else avatarAnimByPic.delete(p.avatar);
  const w = avatarAnimWait.get(p.avatar);
  if (w) w.forEach((f) => { try { f(); } catch {} });
  clearTimeout(avatarAnimSaveT);
  avatarAnimSaveT = setTimeout(() => { try { localStorage.setItem('zchat-avatar-anims', JSON.stringify([...avatarAnimByPic].slice(-300))); } catch {} }, 1500);
}
function useAvatarAnimFor(pic, given) {
  const ok = !given && typeof pic === 'string' && pic.indexOf('http') === 0;
  const [, bump] = useState(0);
  useEffect(() => {
    if (!ok) return undefined;
    let set = avatarAnimWait.get(pic);
    if (!set) { set = new Set(); avatarAnimWait.set(pic, set); }
    const f = () => bump((n) => n + 1);
    set.add(f);
    return () => { set.delete(f); if (!set.size) avatarAnimWait.delete(pic); };
  }, [ok, pic]);
  return given || (ok ? avatarAnimByPic.get(pic) || null : null);
}
function avatarAnimPathOf(url, uid) {
  const s = String(url || '');
  const i = uid ? s.lastIndexOf(`${uid}/`) : -1;
  if (i < 0) return null;
  let p = s.slice(i).split(/[?#]/)[0];
  try { p = decodeURIComponent(p); } catch {}
  return AVATAR_ANIM_PATH.test(p) ? p : null;
}
const NO_PROFILE_ROW = { code: 'PGRST116', message: 'No profile found' };
export function profileFnMissing(error) {
  return !!error && /PGRST202|42883|could not find the function|does not exist/i.test(`${error.code || ''} ${error.message || ''}`);
}
async function sessionUserId() {
  try { const { data } = await supabase.auth.getSession(); return (data && data.session && data.session.user && data.session.user.id) || null; } catch { return null; }
}
export async function fetchMyProfile() {
  const { data, error } = await supabase.rpc('zchat_my_profile');
  if (!error && data && data.hide_photo && !data.avatar_anim) {
    try { const r = await supabase.rpc('zchat_my_avatar_anim'); if (!r.error && typeof r.data === 'string' && r.data) data.avatar_anim = r.data; } catch {}
  }
  if (!error) return data ? { data, error: null } : { data: null, error: NO_PROFILE_ROW };
  if (!profileFnMissing(error)) return { data: null, error };
  const uid = await sessionUserId();
  return uid ? supabase.from('profiles').select('*').eq('id', uid).single() : { data: null, error: NO_PROFILE_ROW };
}
export async function fetchProfilesView(ids, opts) {
  const list = [...new Set((ids || []).filter(Boolean).map(String))];
  if (!list.length) return { data: [], error: null };
  let res = await supabase.rpc('zchat_profile_view', { p_ids: list });
  if (res.error && profileFnMissing(res.error)) res = await supabase.from('profiles').select('*').in('id', list);
  if (res.error) return { data: null, error: res.error };
  const rows = (Array.isArray(res.data) ? res.data : []).map(botPic);
  rows.forEach(noteAvatarAnim);
  return { data: opts && opts.live ? rows.filter((r) => r && !r.is_deleted) : rows, error: null };
}
async function fetchProfileView(id) {
  const { data, error } = await fetchProfilesView([id]);
  return { data: data && data[0] ? data[0] : null, error };
}
export async function getProfile(userId) {
  if (!userId) return { data: null, error: NO_PROFILE_ROW };
  if (userId === (await sessionUserId())) return fetchMyProfile();
  const { data, error } = await fetchProfileView(userId);
  if (error) return { data: null, error };
  return data ? { data, error: null } : { data: null, error: NO_PROFILE_ROW };
}
async function searchByUsername(query) {
  const { data, error } = await supabase.from('profiles').select(PROFILE_COLS).ilike('username', `%${query}%`).limit(20);
  return { data: (data || []).map(botPic), error };
}
export async function updateProfile(userId, fields) {
  const { data, error } = await supabase.from('profiles').update(fields).eq('id', userId).select(PROFILE_SAVE_COLS).single();
  return { data: data ? { ...data, ...fields } : data, error };
}
async function createProfile(userId, username, name, extra) {
  const { data, error } = await supabase.from('profiles').insert({ id: userId, username, name, ...(extra || {}) }).select(PROFILE_SAVE_COLS).single();
  return { data: data ? { ...data, id: userId, username, name } : data, error };
}
const SAFE_UPLOAD_TYPE = /^(image\/(jpeg|jpg|pjpeg|png|webp|gif|heic|heif|avif|bmp)|video\/[a-z0-9.+-]+|audio\/[a-z0-9.+-]+|application\/pdf|text\/plain|text\/csv)$/i;
export function safeUploadType(type) {
  const t = String(type || '').toLowerCase().split(';')[0].trim();
  return SAFE_UPLOAD_TYPE.test(t) ? t : 'application/octet-stream';
}
export function safeUploadFile(file) {
  try {
    if (!file || typeof Blob === 'undefined' || !(file instanceof Blob)) return file;
    const t = safeUploadType(file.type);
    if (t === String(file.type || '').toLowerCase()) return file;
    return new File([file], file.name || 'file', { type: t });
  } catch { return file; }
}
const WEB_PHOTO = /^image\/(jpeg|jpg|pjpeg|png|webp|gif)$/i;
function photoNameJpg(name) { return `${String(name || 'photo').replace(/\.[a-z0-9]{2,5}$/i, '') || 'photo'}.jpg`; }
async function decodePhoto(file) {
  if (typeof createImageBitmap === 'function') {
    try { const bmp = await createImageBitmap(file); if (bmp && bmp.width && bmp.height) return { src: bmp, w: bmp.width, h: bmp.height, close: () => { try { bmp.close(); } catch {} } }; } catch {}
  }
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((resolve, reject) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = () => reject(new Error('decode')); im.src = url; });
    return { src: img, w: img.naturalWidth, h: img.naturalHeight, close: () => URL.revokeObjectURL(url) };
  } catch (e) { URL.revokeObjectURL(url); throw e; }
}
export async function toWebPhoto(file) {
  if (!file || typeof Blob === 'undefined' || !(file instanceof Blob)) return file;
  const type = String(file.type || '').toLowerCase();
  const isImage = type.indexOf('image/') === 0 || (!type && /\.(heic|heif|avif|jpe?g|png|webp|gif|bmp|tiff?)$/i.test(String(file.name || '')));
  if (!isImage) return file;
  if (WEB_PHOTO.test(type)) {
    if (file.size > 25 * 1024 * 1024) return file;
    try { const buf = await file.arrayBuffer(); return new File([buf], file.name || 'photo', { type: type === 'image/jpg' || type === 'image/pjpeg' ? 'image/jpeg' : type }); } catch { return file; }
  }
  const pic = await decodePhoto(file);
  try {
    const scale = Math.min(1, 4096 / Math.max(pic.w, pic.h), Math.sqrt(16000000 / Math.max(1, pic.w * pic.h)));
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(pic.w * scale));
    canvas.height = Math.max(1, Math.round(pic.h * scale));
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(pic.src, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.9));
    if (!blob) throw new Error('encode');
    return new File([blob], photoNameJpg(file.name), { type: 'image/jpeg' });
  } finally { pic.close(); }
}
export function photoFailText(e) {
  return /decode|encode/i.test(String((e && e.message) || '')) ? 'That photo could not be opened on this phone. Try another photo.' : '';
}
export async function uploadMedia(file, userId) {
  let f = file;
  try { f = await toWebPhoto(file); } catch (e) { return { url: null, error: { message: photoFailText(e) || 'That photo could not be opened. Try another photo.' } }; }
  return uploadMediaRaw(safeUploadFile(f), userId);
}

function CountryPicker({ value, onSelect, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const filtered = COUNTRIES.filter(([, name]) => name.toLowerCase().includes(q.toLowerCase()));
  return (
    <FullPage title="Country" subtitle="Shown on your profile" onBack={onClose} zIndex={96}>
      <label style={{ display: 'flex', alignItems: 'center', gap: 8, height: 40, padding: '0 12px', borderRadius: 12, background: theme.rowBg, color: theme.muted, margin: '8px 0 8px' }}>
        <Search size={17} />
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search countries" aria-label="Search countries" autoCapitalize="none" enterKeyHint="search"
          style={{ flex: 1, minWidth: 0, border: 0, outline: 0, background: 'transparent', color: theme.ink, fontFamily: FONT, fontSize: 15 }} />
        {q && <X size={16} style={{ cursor: 'pointer' }} onClick={() => setQ('')} />}
      </label>
      {value && !q && (
        <div role="button" aria-label="Remove country" onClick={() => { onSelect(''); onClose(); }} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 2px', cursor: 'pointer', color: theme.danger, fontSize: 15, fontWeight: 700 }}>
          <X size={18} />Remove country from my profile
        </div>
      )}
      {filtered.length === 0 && <EmptyState art="search" title="No country matches" text="Try a different spelling." />}
      {filtered.map(([code, name]) => (
        <div key={code} role="button" aria-label={name} onClick={() => { onSelect(code); onClose(); }} style={{
          display: 'flex', alignItems: 'center', gap: 14, padding: '11px 2px', cursor: 'pointer', minHeight: 50,
        }}>
          <span style={{ fontSize: 26, width: 34, textAlign: 'center', lineHeight: 1 }}>{countryFlag(code)}</span>
          <span style={{ fontSize: 15, color: theme.ink, fontWeight: value === code ? 800 : 500, flex: 1 }}>{name}</span>
          {value === code && <Check size={18} color={theme.coral} strokeWidth={2.6} />}
        </div>
      ))}
    </FullPage>
  );
}


