export function SpotArt({ k, dark = false, radius = 22, style }) {
  const sc = SPOT_SCENES[k] || SPOT_SCENES.chats;
  const pair = ART_BG[sc.bg] || ART_BG.lilac;
  const bg = dark ? pair[1] : pair[0];
  return (
    <ArtCtx.Provider value={!!dark}>
      <svg viewBox="0 0 320 180" preserveAspectRatio="xMidYMid slice" aria-hidden="true" style={{ display: 'block', width: '100%', aspectRatio: '2 / 1', borderRadius: radius, background: bg, ...(style || {}) }}>
        {sc.draw(bg)}
      </svg>
    </ArtCtx.Provider>
  );
}
export function LoadFail({ code, onRetry, small, where }) {
  const { theme } = useTheme();
  const c = code ? String(code) : '';
  const boxRef = useRef(null);
  useEffect(() => {
    if (!c) return;
    let w = where || '';
    try { if (!w && boxRef.current) { const host = boxRef.current.closest('[data-zwhere]'); if (host) w = host.getAttribute('data-zwhere') || ''; } } catch {}
    reportClientError(`Did not load: ${w || 'a page'} (code ${c})`, '', { kind: 'load', code: c, where: w || null });
  }, [c, where]);
  return (
    <div ref={boxRef} role="alert" style={{ textAlign: 'center', padding: small ? '18px 16px' : '56px 24px 40px', color: theme.muted }}>
      <div style={{ fontSize: small ? 15 : 17, fontWeight: 800, color: theme.ink, letterSpacing: '-0.01em' }}>This did not load</div>
      <div style={{ fontSize: small ? 13 : 14, lineHeight: 1.5, marginTop: 6, maxWidth: 320, marginLeft: 'auto', marginRight: 'auto', textWrap: 'balance' }}>{c ? 'ZChat could not load this right now. Try again in a moment.' : 'Check your connection, then try again.'}</div>
      {onRetry && <div style={{ marginTop: 16, display: 'flex', justifyContent: 'center' }}><PillButton primary label="Try again" onClick={onRetry} /></div>}
      {c && <div style={{ marginTop: 10, fontSize: 11.5, opacity: 0.7 }}>Code {c}</div>}
    </div>
  );
}

function LazyFail({ onRetry }) {
  const { theme } = useTheme();
  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 3000, background: theme.bgGradient, display: 'flex', alignItems: 'center', justifyContent: 'center', paddingTop: 'env(safe-area-inset-top)', paddingBottom: 'env(safe-area-inset-bottom)' }}>
      <LoadFail onRetry={onRetry} />
    </div>
  );
}

function LazyWait() {
  const { theme } = useTheme();
  return (
    <div aria-hidden="true" style={{ position: 'fixed', left: 0, right: 0, top: 'calc(50% - 22px)', display: 'flex', justifyContent: 'center', zIndex: 2999, pointerEvents: 'none' }}>
      <div style={{ width: 44, height: 44, borderRadius: 22, background: theme.panelBg, boxShadow: '0 6px 22px rgba(0,0,0,0.22)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spinner size={18} color={theme.coral} />
      </div>
    </div>
  );
}

zLazySetUi({ Fail: LazyFail, Wait: LazyWait });

export function EmptyState({ icon, art, title, text, action }) {
  const { theme } = useTheme();
  return (
    <div style={{ textAlign: 'center', padding: art ? '16px 8px 34px' : '56px 24px 40px', color: theme.muted }}>
      {art ? <div style={{ maxWidth: 300, margin: '0 auto 18px' }}><SpotArt k={art} dark={theme.dark} /></div> : icon && <div style={{ margin: '0 auto 12px', color: theme.muted, display: 'flex', justifyContent: 'center' }}>{React.isValidElement(icon) ? React.cloneElement(icon, { size: 42, strokeWidth: 1.4 }) : icon}</div>}
      <div style={{ fontSize: 17, fontWeight: 800, color: theme.ink, letterSpacing: '-0.01em', textWrap: 'balance' }}>{title}</div>
      {text && <div style={{ fontSize: 14, lineHeight: 1.55, marginTop: 6, maxWidth: 330, marginLeft: 'auto', marginRight: 'auto', textWrap: 'balance' }}>{text}</div>}
      {action && <div style={{ marginTop: 18, display: 'flex', justifyContent: 'center' }}>{action}</div>}
    </div>
  );
}

export function PillButton({ label, onClick, primary, danger, disabled, small, style, ariaLabel }) {
  const { theme } = useTheme();
  const solid = primary || danger;
  return (
    <button aria-label={ariaLabel || (typeof label === 'string' ? label : undefined)} onClick={(e) => { e.stopPropagation(); if (!disabled && onClick) onClick(e); }} disabled={disabled} className="zchat-press" style={{
      height: small ? 32 : 36, padding: small ? '0 13px' : '0 16px', borderRadius: 10, flexShrink: 0, whiteSpace: 'nowrap',
      border: solid ? 'none' : `1px solid ${theme.border}`, background: primary ? theme.coral : danger ? theme.danger : theme.rowBg,
      color: solid ? 'white' : theme.ink, fontWeight: 800, fontSize: small ? 12.5 : 13.5, fontFamily: FONT,
      cursor: disabled ? 'default' : 'pointer', opacity: disabled ? 0.55 : 1, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6, ...(style || {}),
    }}>{label}</button>
  );
}

export const CLOSE_GREEN = '#1DB954';

function RequestsIcon({ size = 22, color = 'currentColor' }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M4 5.5h16v10H9l-5 4z" /><path d="M9 9.5h6M9 12.5h4" />
    </svg>
  );
}

function RequestBar({ name, onAccept, onDelete, onBlock, busy }) {
  const { theme } = useTheme();
  const first = String(name || 'They').split(' ')[0];
  const btn = (label, onClick, tone) => (
    <div role="button" aria-label={`${label} request`} onClick={busy ? undefined : onClick} className="zchat-press"
      style={{ flex: 1, textAlign: 'center', padding: '11px 0', borderRadius: 14, fontSize: 14.5, fontWeight: 800, cursor: busy ? 'default' : 'pointer', background: tone === 'accent' ? theme.coral : theme.rowBg, color: tone === 'accent' ? '#FFFFFF' : tone === 'danger' ? theme.danger : theme.ink, opacity: busy ? 0.6 : 1 }}>{label}</div>
  );
  return (
    <div className="zchat-fade" style={{ flex: 1, minWidth: 0, padding: '6px 0 2px' }}>
      <div style={{ fontSize: 14.5, fontWeight: 800, color: theme.ink, textAlign: 'center' }}>{first} wants to chat with you</div>
      <div style={{ fontSize: 12.5, color: theme.muted, textAlign: 'center', margin: '4px 6px 10px', lineHeight: 1.45 }}>{first} will not see that you read this until you accept.</div>
      <div style={{ display: 'flex', gap: 8 }}>
        {btn('Block', onBlock, 'danger')}
        {btn('Delete', onDelete)}
        {btn('Accept', onAccept, 'accent')}
      </div>
    </div>
  );
}

function DmClosedBar({ name }) {
  const { theme } = useTheme();
  const first = String(name || 'They').split(' ')[0];
  return (
    <div className="zchat-fade" style={{ flex: 1, textAlign: 'center', padding: '10px 6px', fontSize: 12.5, color: theme.muted, fontWeight: 600, lineHeight: 1.45 }}>
      {first} only gets messages from people they follow.
    </div>
  );
}

