async function canInteract(kind, fromId, toId) {
  if (!fromId || !toId || fromId === toId) return true;
  try {
    const { data, error } = await supabase.rpc('zchat_can_interact', { p_kind: kind, p_from: fromId, p_to: toId });
    if (error) return true;
    return data !== false;
  } catch { return true; }
}

