export async function giftRpc(name, args, label) {
  let res;
  try { res = await supabase.rpc(name, args); } catch (e) { res = { error: e }; }
  const row = res && !res.error ? (Array.isArray(res.data) ? res.data[0] : res.data) : null;
  if (res.error) return { error: res.error.code === 'P0001' && res.error.message ? res.error.message : rpcFailText(label, res.error, 'This switches on once the latest ZChat setup is finished.'), missing: rpcMissing(res.error) };
  if (!row || row.ok === false) return { error: (row && row.reason) || 'That did not work. Try again.', row };
  return { ok: true, row };
}
export const GIFT_MAX = 1000;
export const giftTheirsMem = new Map();
export const giftTheirsPend = new Map();

export const rewardOpt = { rows: [], set: null };
function rewardOptMerge(list) {
  const base = Array.isArray(list) ? list : [];
  const extra = rewardOpt.rows.filter((p) => !base.some((r) => r.kind === p.kind && r.reward_key === p.reward_key && !r.expires_at));
  return extra.length ? [...base, ...extra] : base;
}
function rewardOptLoaded(list, started) {
  rewardOpt.rows = rewardOpt.rows.filter((r) => !(r.done && r.done <= started));
  return rewardOptMerge(list);
}
function rewardOptAdd(uid, pairs) {
  if (!pairs || !pairs.length) return null;
  const tag = `opt${Date.now()}${Math.random().toString(36).slice(2, 7)}`;
  const at = new Date().toISOString();
  rewardOpt.rows = [...rewardOpt.rows, ...pairs.map(([kind, key]) => ({ id: null, user_id: uid, kind, reward_key: key, expires_at: null, seen: true, granted_at: at, created_at: at, opt: tag }))];
  if (rewardOpt.set) rewardOpt.set((prev) => rewardOptMerge((prev || []).filter((r) => !r.opt)));
  pairs.forEach(([kind, key]) => { if (kind === 'bubble') ownedBubblesMark(uid, key, true); });
  return tag;
}
function rewardOptEnd(tag, ok) {
  if (!tag) return;
  const mine = rewardOpt.rows.filter((r) => r.opt === tag);
  if (ok) { rewardOpt.rows = rewardOpt.rows.map((r) => (r.opt === tag ? { ...r, done: Date.now() } : r)); return; }
  rewardOpt.rows = rewardOpt.rows.filter((r) => r.opt !== tag);
  if (rewardOpt.set) rewardOpt.set((prev) => (prev || []).filter((r) => r.opt !== tag));
  mine.forEach((r) => { if (r.kind === 'bubble') ownedBubblesMark(r.user_id, r.reward_key, false); });
}
export function moneyRun(uid, { coins = 0, freeSets = 0, freeBubbles = 0, grants = [], run }) {
  const change = {};
  if (coins) change.coins = -coins;
  if (freeSets) change.freeSets = -freeSets;
  if (freeBubbles) change.freeBubbles = -freeBubbles;
  const tok = Object.keys(change).length ? walletSpend(uid, change) : null;
  const tag = rewardOptAdd(uid, grants);
  const end = (r) => {
    const res = r && (r.ok || r.error) ? r : { error: 'That did not work. Try again.' };
    walletAfter(uid, tok, res.error ? { error: true } : { coins: res.coins, set: res.set });
    rewardOptEnd(tag, !res.error);
    if (!res.error && grants.some(([kind]) => kind === 'bubble')) loadOwnedBubbles(uid, true);
    return res;
  };
  return Promise.resolve().then(run).then(end, () => end({ error: 'That did not work. Try again.' }));
}
export const moneyToastSubs = new Set();
function moneyToast(text) {
  let hit = false;
  moneyToastSubs.forEach((fn) => { try { if (fn(text)) hit = true; } catch {} });
  return hit;
}

const achToastMem = { ran: false };
async function runAchievementCheck(uid, extra) {
  const keys = await checkMyAchievements(uid, extra);
  if (keys && keys.length) {
    try { window.dispatchEvent(new CustomEvent('zchat-achievements', { detail: { keys } })); } catch {}
  }
  return keys;
}
function AchToastHost({ busy, showingRef, onOpen, onChange }) {
  const [k, setK] = useState(null);
  const cbRef = useRef(null);
  cbRef.current = { onOpen, onChange };
  useEffect(() => {
    const onAch = (e) => { const key = e && e.detail && e.detail.keys && e.detail.keys[0]; if (!key) return; showingRef.current = true; setK(key); if (cbRef.current.onChange) cbRef.current.onChange(); };
    window.addEventListener('zchat-achievements', onAch);
    return () => { window.removeEventListener('zchat-achievements', onAch); showingRef.current = false; };
  }, []);
  const clear = () => { showingRef.current = false; setK(null); if (cbRef.current.onChange) cbRef.current.onChange(); };
  if (!k || busy) return null;
  return <AchievementToast k={k} onDone={clear} onOpen={() => { clear(); if (cbRef.current.onOpen) cbRef.current.onOpen(); }} />;
}

function AchievementToast({ k, onOpen, onDone }) {
  const { theme } = useTheme();
  useEffect(() => { const t = setTimeout(onDone, 4200); return () => clearTimeout(t); }, [k]);
  const a = ACH_BY_KEY[k];
  if (!a) return null;
  return (
    <Portal>
      <div role="status" onClick={onOpen} className="zchat-pop" style={{ position: 'fixed', left: 12, right: 12, bottom: 'calc(80px + env(safe-area-inset-bottom))', zIndex: 950, maxWidth: 440, margin: '0 auto', display: 'flex', alignItems: 'center', gap: 12, padding: '10px 14px 10px 10px', borderRadius: 18, background: theme.dark ? '#26252C' : '#FFFFFF', boxShadow: '0 12px 34px rgba(0,0,0,0.25)', cursor: 'pointer', fontFamily: FONT }}>
        <AchievementArt k={k} size={44} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 12.5, color: theme.muted, fontWeight: 600 }}>New achievement</div>
          <div style={{ fontSize: 15.5, fontWeight: 800, color: theme.ink }}>{a.title}</div>
        </div>
        <ChevronRight size={18} color={theme.muted} />
      </div>
    </Portal>
  );
}

function md(d) { return `${d.getMonth()}-${d.getDate()}`; }
export async function loadAnniversaries(uid) {
  const [mine, theirs] = await Promise.all([
    supabase.from('follows').select('following_id, created_at').eq('follower_id', uid).eq('status', 'accepted').limit(3000),
    supabase.from('follows').select('follower_id, created_at').eq('following_id', uid).eq('status', 'accepted').limit(3000),
  ]);
  const a = new Map(((mine && mine.data) || []).map((r) => [r.following_id, r.created_at]));
  const today = new Date();
  const out = [];
  ((theirs && theirs.data) || []).forEach((r) => {
    const other = a.get(r.follower_id);
    if (!other || !r.created_at) return;
    const start = new Date(Math.max(new Date(other).getTime(), new Date(r.created_at).getTime()));
    const years = today.getFullYear() - start.getFullYear();
    if (years >= 1 && md(start) === md(today)) out.push({ id: r.follower_id, years, since: start.toISOString() });
  });
  return out;
}
function AnniversaryBanner({ people, onSay, onDismiss }) {
  const { theme } = useTheme();
  if (!people.length) return null;
  const first = people[0];
  const name = String((first.profile && first.profile.name) || '').split(' ')[0] || 'A friend';
  const label = people.length === 1 ? `You and ${name} met here ${first.years === 1 ? 'a year' : `${first.years} years`} ago today` : `${people.length} friendship anniversaries today`;
  return (
    <div style={{ margin: '0 6px 10px', padding: '10px 6px 10px 14px', borderRadius: 16, background: theme.rowBg, display: 'flex', alignItems: 'center', gap: 12 }}>
      <span style={{ display: 'flex', color: theme.coral, flexShrink: 0 }}><FriendshipIcon size={22} /></span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>
        <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 1 }}>Friendship anniversary</div>
      </div>
      {first.profile && <div role="button" aria-label={`Say hi to ${first.profile.name}`} onClick={() => onSay(first)} className="zchat-press" style={{ padding: '8px 8px', color: theme.coral, fontSize: 14, fontWeight: 800, cursor: 'pointer', flexShrink: 0 }}>Say hi</div>}
      <div role="button" aria-label="Hide friendship anniversary" onClick={onDismiss} style={{ padding: 8, cursor: 'pointer', color: theme.muted, display: 'flex', flexShrink: 0 }}><X size={16} /></div>
    </div>
  );
}

