  if (top === undefined) return <div style={{ gridColumn: '1 / -1', padding: 24, display: 'flex', justifyContent: 'center' }}><Spinner size={18} color={theme.muted} /></div>;
  if (!list.length) return <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: 20, fontSize: 12.5, color: theme.muted, lineHeight: 1.5 }}>Packs made by people on ZChat show up here once they go on sale</div>;
