  const tabs = [{ k: 'all', label: 'All' }, { k: 'general', label: 'General' }, ...topics.map((t) => ({ k: t.id, label: t.n, dot: t.c }))]
    .map((t) => ({ ...t, aria: `Topic ${t.label}`, mark: !!(unread && unread[t.k]) }));
