function pgViewsText(n) {
  const v = Math.max(0, Math.floor(Number(n) || 0));
  const cut = (x, d) => (Math.floor(x / d) / 10).toFixed(1).replace(/\.0$/, '');
  if (v < 1000) return String(v);
  if (v < 1e6) return `${cut(v, 100)}K`;
  if (v < 1e9) return `${cut(v, 1e5)}M`;
  return `${cut(v, 1e8)}B`;
}
