    if (document.getElementById('zchat-pg-style')) return;
    const st = document.createElement('style');
    st.id = 'zchat-pg-style';
    st.textContent = '@keyframes zpg-in{from{opacity:0}to{opacity:1}}.zpg-views{animation:zpg-in .22s ease-out both}@keyframes zpg-flash{0%{opacity:0}14%{opacity:1}62%{opacity:1}100%{opacity:0}}.zpg-flash::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 0 3px var(--zpg-ring,#8B5CF6);background:rgba(255,255,255,.16);animation:zpg-flash 1.6s ease-out forwards}@keyframes zpg-pill{from{opacity:0;transform:translateY(12px) scale(.94)}to{opacity:1;transform:none}}.zpg-pill{animation:zpg-pill .26s cubic-bezier(.2,.8,.2,1) both}@media (prefers-reduced-motion: reduce){.zpg-views,.zpg-pill{animation:none}}';
    document.head.appendChild(st);
