export const bdayForMem = new Map();
function bdayDaysTo(md) {
  const [m, d] = String(md || '').split('-').map((n) => parseInt(n, 10));
  if (!m || !d) return null;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const at = (y) => { const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; return new Date(y, m - 1, m === 2 && d === 29 && !leap ? 28 : d); };
  let t = at(today.getFullYear());
  if (t < today) t = at(today.getFullYear() + 1);
  return Math.round((t - today) / 86400000);
}
