  if (mentionBot.p) return Promise.resolve(mentionBot.p);
  if (!mentionBot.p) { try { const v = JSON.parse(localStorage.getItem('zchat-mention-bot') || 'null'); if (v && v.id && v.username) mentionBot.p = v; } catch {} }
  if (mentionBot.job) return mentionBot.job;
  mentionBot.job = Promise.resolve(supabase.from('profiles').select('id, name, username, avatar, is_deleted, is_bot, verified').eq('is_bot', true).limit(5))
    .then(({ data }) => { const b = (data || []).find((x) => x && x.username === BOT_MENTION.slice(1)) || (data || [])[0]; if (b && b.id) { mentionBot.p = b; try { localStorage.setItem('zchat-mention-bot', JSON.stringify(b)); } catch {} } return mentionBot.p; }, () => mentionBot.p);
