      const a = superAnchor(msgId);
      if (!a || a.bottom < 0 || a.top > window.innerHeight) return;
      try {
        window.ZSRX.play(cv, key, { x: a.x, y: a.y, tx: a.tx, ty: a.ty, el: a.el, dark: superFx.dark, dprCap: superDpr(), solo: true, onError: (e) => reportClientError(`Super reaction ${key}: ${(e && e.message) || e}`, e && e.stack, { kind: 'fx' }) });
      } catch {}
