            <ViewerButton label="Save video" onClick={() => silentDownload(url, 'zchat-video.mp4')}><Download size={21} /></ViewerButton>
            {onForward && <ViewerButton label="Forward" onClick={onForward}><Forward size={21} /></ViewerButton>}
          </>
