export async function silentDownload(rawUrl, filename) {
  try {
    const url = await resolveMedia(rawUrl);
    if (!url) return false;
    const res = await fetch(url);
    if (!res.ok) throw new Error('download');
    const blob = await res.blob();
    if (/gif/i.test(blob.type || '')) filename = String(filename).replace(/\.(jpe?g|png|webp)$/i, '.gif');
    const file = new File([blob], filename, { type: blob.type || 'application/octet-stream' });
    if (isAppleMobile() && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file] });
        return true;
      } catch (err) {
        if (err && err.name === 'AbortError') return false;
      }
    }
    const blobUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(blobUrl), 4000);
    return true;
  } catch {
    return false;
  }
}

