  useEffect(() => () => { clearTimeout(holdRef.current.t); clearTimeout(holdRef.current.hide); }, []);
  if (!pins.length) return null;
  const current = pins[Math.min(index, pins.length - 1)];
  const preview = describeMessage(current);
  const hold = holdRef.current;
  const stop = () => clearTimeout(hold.t);
  const showLeft = () => { hold.fired = true; hapticTap(); setLeft(pinLeftText(current.pinned_until)); clearTimeout(hold.hide); hold.hide = setTimeout(() => setLeft(null), 2600); };
