    const [local] = await Promise.all([getMedia(kind), waitIce()]);
    if (!local || !callRef.current || callRef.current.id !== row.call_id) { if (local) local.getTracks().forEach((t) => t.stop()); if (callRef.current && callRef.current.id === row.call_id) put(null); return; }
    localRef.current = local;
