    const targets = c.mode === 'direct' ? [peer && peer.id].filter(Boolean) : (Array.isArray(st.participants) ? st.participants : []).filter((id) => typeof id === 'string');
    const group = c.group && (c.group.avatar || !st.group) ? c.group : (st.group || c.group);
    patch({ moving: false, direction: st.direction === 'incoming' ? 'incoming' : 'outgoing', startedAt: Number(st.startedAt) || c.startedAt, peer, group, participants: c.mode === 'group' ? targets : [] });
