    if (vroomCtl.gid !== gid || !data || data.ok === false || !Array.isArray(data.muted)) return;
    vroomCtl.groupMuted = new Set(data.muted.map((m) => m && m.user_id).filter(Boolean));
    const eng = liveCallHub.engine;
    const me = vroomCtl.me && vroomCtl.me.id;
    if (me && vroomCtl.groupMuted.has(me)) { voiceRoomLeave('muted'); appSnack('You are muted in this group for now, so you left the voice room'); return; }
