  if (!gid) return Promise.resolve(false);
  if (vroomCtl.refreshJob) return vroomCtl.refreshJob;
  if (Date.now() - vroomCtl.refreshAt < 10000) return Promise.resolve(false);
  vroomCtl.refreshAt = Date.now();
  vroomCtl.refreshJob = Promise.resolve(supabase.from('group_members').select('user_id, role').eq('group_id', gid).limit(3000)).then(({ data }) => {
    vroomCtl.refreshJob = null;
    if (vroomCtl.gid !== gid || !Array.isArray(data) || !data.length) return false;
    vroomCtl.roles = vroomRolesFrom(data);
    return true;
  }, () => { vroomCtl.refreshJob = null; return false; });
  return vroomCtl.refreshJob;
