function followLabel(state, theyFollowMe) {
  if (state === 'accepted') return 'Following';
  if (state === 'pending') return 'Requested';
  return theyFollowMe ? 'Follow back' : 'Follow';
}
const latestSyncMem = new Map();
export function latestSync(keyIn, want, run, base) {
  const key = `${cacheOwner}|${keyIn}`;
  let s = latestSyncMem.get(key);
  if (!s) { s = { want, base, job: null }; latestSyncMem.set(key, s); }
  s.want = want;
  if (s.job) return s.job;
  s.job = (async () => {
    let sent;
    let error = null;
    while (sent !== s.want) {
      const w = s.want;
      let res;
      try { res = await run(w); } catch (e) { res = { error: e }; }
      if (res && res.error) { error = res.error; break; }
      sent = w;
    }
    latestSyncMem.delete(key);
    return { ok: !error, error, state: error && sent === undefined ? s.base : sent };
  })();
  return s.job;
}
const followSyncMem = new Map();
export function followSync(myId, theirId, want, from) {
  const key = `${myId}:${theirId}`;
  let s = followSyncMem.get(key);
  if (!s) { s = { want, base: from || 'none', job: null }; followSyncMem.set(key, s); }
  s.want = want;
  try { window.dispatchEvent(new CustomEvent('zchat-follow-change', { detail: { id: theirId, state: want } })); } catch {}
  if (s.job) return s.job;
  s.job = (async () => {
    let sent = null;
    let error = null;
    while (sent !== s.want) {
      const w = s.want;
      let res = null;
      try {
        res = w === 'none'
          ? await supabase.from('follows').delete().eq('follower_id', myId).eq('following_id', theirId)
          : await supabase.from('follows').insert({ follower_id: myId, following_id: theirId, status: w });
      } catch (e) { res = { error: e }; }
      if (res && res.error && !(w !== 'none' && /duplicate|unique/i.test(String(res.error.message || '')))) { error = res.error; break; }
      sent = w;
    }
    followSyncMem.delete(key);
    const state = error ? (sent || s.base) : sent;
    if (error) { try { window.dispatchEvent(new CustomEvent('zchat-follow-change', { detail: { id: theirId, state } })); } catch {} }
    else if (state !== 'none') { try { window.dispatchEvent(new Event('zchat-follows-stale')); } catch {} }
    return { ok: !error, error, state };
  })();
  return s.job;
}

export function FollowActionButton({ state, theyFollowMe, busy, onClick, size = 'md', onDark = false }) {
  const { theme } = useTheme();
  const filled = state !== 'accepted' && state !== 'pending';
  const dims = size === 'sm' ? { width: 104, height: 32, fontSize: 12, radius: 10 } : size === 'pill' ? { width: '100%', height: 36, fontSize: 14, radius: 10 } : { width: '100%', height: 46, fontSize: 14, radius: 12 };
  return (
    <button onClick={(e) => { e.stopPropagation(); if (!busy) onClick(); }} disabled={busy} style={{
      width: dims.width, minWidth: dims.width, height: dims.height, borderRadius: dims.radius, flexShrink: 0, boxSizing: 'border-box',
      display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, cursor: busy ? 'default' : 'pointer', fontFamily: FONT,
      fontSize: dims.fontSize, fontWeight: 700, letterSpacing: 0.1, transition: 'background 0.2s ease, color 0.2s ease',
      border: filled || size === 'pill' ? 'none' : `1px solid ${onDark ? 'rgba(255,255,255,0.45)' : theme.border}`,
      background: filled ? theme.coral : (onDark ? 'rgba(0,0,0,0.35)' : (size === 'sm' ? theme.rowBg : size === 'pill' ? theme.soft : (theme.dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)'))),
      color: filled || onDark ? 'white' : theme.ink,
    }}>
      {busy ? <Spinner size={13} color={filled || onDark ? 'white' : theme.ink} /> : followLabel(state, theyFollowMe)}
    </button>
  );
}

export const BADGE_SHAPE_PATH = (() => {
  const lobes = 12;
  const steps = 144;
  const radius = 9.9;
  const depth = 0.075;
  let d = '';
  for (let i = 0; i <= steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    const r = radius * (1 - depth * Math.cos(lobes * a));
    const x = 12 + r * Math.cos(a - Math.PI / 2);
    const y = 12 + r * Math.sin(a - Math.PI / 2);
    d += `${i ? 'L' : 'M'}${x.toFixed(2)} ${y.toFixed(2)}`;
  }
  return `${d}Z`;
})();

