  const still = paused || reducedMotion();
  const runs = nsRuns(text);
  if (own) return <NsOwnName refEl={ref} own={own} runs={runs} dark={isDark} sub={sub} plate={plate} still={still} />;
  const wave = k === 'ripple' && !sub && !still;
