  '.zns-own.zom-pulse .zt{background-image:linear-gradient(90deg,var(--o1),var(--o2),var(--o3),var(--o2),var(--o1));background-size:240% 100%;animation:zns-drift 5s ease-in-out infinite alternate,zns-opulse 2.6s ease-in-out infinite}',
