          {bars.map((b, i) => (
            <div key={i} style={{ flex: 1, height: `${Math.round(b * 100)}%`, minHeight: 3, borderRadius: 2, background: (i + 0.5) / bars.length <= pct ? active : idle, transition: 'background 0.15s linear' }} />
          ))}
