export function rewardActive(r) {
  return !r.expires_at || new Date(r.expires_at).getTime() > Date.now();
}

export function daysLeft(r) {
  if (!r || !r.expires_at) return null;
  return Math.max(0, Math.ceil((new Date(r.expires_at).getTime() - Date.now()) / 86400000));
}
export const fxPackJobs = new Map();
try {
  if (typeof window !== 'undefined') window.addEventListener('online', () => { fxPackJobs.forEach((job, src) => { job.then((ok) => { if (!ok && fxPackJobs.get(src) === job) fxPackJobs.delete(src); }); }); });
} catch {}
export function fxDprCap() {
  try {
    const nav = navigator;
    const ua = nav.userAgent || '';
    const cores = nav.hardwareConcurrency || 4;
    const mem = nav.deviceMemory || 4;
    if (/iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && nav.maxTouchPoints > 1)) return 1.5;
    if (/Android/i.test(ua)) return cores >= 8 && mem >= 8 ? 1.25 : 1;
    return 1.5;
  } catch {
    return 1;
  }
}
