  const still = reducedMotion() || !prefOn('zchat-profile-fx');
  const mask = 'linear-gradient(180deg, #000 0px, #000 calc(100% - 190px), rgba(0,0,0,0.5) calc(100% - 90px), transparent 100%)';
  const scrim = `linear-gradient(180deg, rgba(${bg},0.3) 0px, rgba(${bg},0) 84px, rgba(${bg},0.06) 46%, rgba(${bg},${theme.dark ? 0.4 : 0.5}) calc(100% - 150px), rgba(${bg},0.7) 100%)`;
