        <div key={i} style={{ position: 'absolute', left: q.x - 34, top: q.y - 22, width: q.w + 68, height: q.h + 44, background: `radial-gradient(closest-side, rgba(${bg},${spotA}) 0%, rgba(${bg},${spotA * 0.85}) 55%, rgba(${bg},0) 100%)` }} />
