export function dropPhase(d, now = Date.now()) {
  if (!d) return 'ended';
  if (now < Date.parse(d.starts_at)) return 'soon';
  return now < Date.parse(d.ends_at) ? 'live' : 'ended';
}
export function shortLeft(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return `${m}m`;
  return `${s}s`;
}
export function useSecondTick(on = true) {
  const [, setTick] = useState(0);
  useEffect(() => {
    if (!on) return undefined;
    const iv = setInterval(() => setTick((n) => n + 1), 1000);
    return () => clearInterval(iv);
  }, [on]);
}
export function dropOwned(drop, rewards) {
  if (!drop) return false;
  if (drop.kind === 'set') return decorOwned(rewards, drop.item_key).full;
  return (rewards || []).some((r) => r.kind === 'bubble' && r.reward_key === drop.item_key && rewardActive(r));
}
export function DropArt({ drop, me, size }) {
  const set = drop.kind === 'set' ? DECOR_BY_KEY[drop.item_key] : null;
  if (set) {
    return (
      <div style={{ position: 'relative', width: size, height: size, flexShrink: 0 }}>
        <div style={{ position: 'absolute', left: '50%', top: '50%', width: Math.round(size * 0.611), height: Math.round(size * 0.611), transform: 'translate(-50%, -50%)', borderRadius: '50%', overflow: 'hidden' }}><Avatar emoji={me && me.avatar} name={me ? me.name : ''} size={Math.round(size * 0.611)} /></div>
        <div style={{ position: 'absolute', inset: 0 }}><DecorArt setKey={set.key} part="frame" width={size} /></div>
      </div>
    );
  }
  return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}><img src={bubbleArtUri(drop.item_key)} alt="" draggable={false} style={{ width: size * 0.8, height: size * 0.8 }} /></div>;
}
function DropCard({ drop, me, rewards, onOpen }) {
  useSecondTick(true);
  const set = drop.kind === 'set' ? DECOR_BY_KEY[drop.item_key] : null;
  const accent = set ? set.accent : '#8B6CFF';
  const phase = dropPhase(drop);
  const owned = dropOwned(drop, rewards);
  const left = phase === 'soon' ? Date.parse(drop.starts_at) - Date.now() : Date.parse(drop.ends_at) - Date.now();
  return (
    <div role="button" aria-label={`Drop ${drop.title}`} onClick={onOpen} className="zchat-press"
      style={{ position: 'relative', overflow: 'hidden', borderRadius: 22, padding: '12px 14px 12px 10px', marginBottom: 12, display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer', background: `radial-gradient(130% 150% at 0% 0%, ${accent}59 0%, rgba(16, 16, 24, 0) 62%), linear-gradient(160deg, #171a2e 0%, #0b0c14 100%)`, boxShadow: `inset 0 0 0 1px ${accent}47` }}>
      <DropArt drop={drop} me={me} size={88} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, height: 22, padding: '0 9px', borderRadius: 11, background: phase === 'live' ? '#FF3B5C' : 'rgba(255, 255, 255, 0.13)', fontSize: 11.5, fontWeight: 800 }}>
          {phase === 'live' && <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#FFFFFF', animation: reducedMotion() ? 'none' : 'zchat-live-dot 1.4s ease-in-out infinite' }} />}
          {phase === 'live' ? 'Drop is live' : phase === 'soon' ? 'Next drop' : 'Drop ended'}
        </div>
        <div style={{ fontSize: 18, fontWeight: 900, marginTop: 6, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{drop.title}</div>
        <div style={{ fontSize: 13, color: 'rgba(255, 255, 255, 0.72)', marginTop: 2, fontVariantNumeric: 'tabular-nums' }}>{owned ? 'Yours to keep' : phase === 'soon' ? `Opens in ${shortLeft(left)}` : phase === 'live' ? `Ends in ${shortLeft(left)}` : 'This drop has ended'}</div>
      </div>
      {!owned && <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontWeight: 800, fontSize: 14.5, flexShrink: 0 }}><CoinIcon size={17} />{formatCount(drop.price)}</div>}
      <ChevronRight size={18} color="rgba(255, 255, 255, 0.5)" style={{ flexShrink: 0 }} />
    </div>
  );
}

export const limitMem = { uid: null, data: null, at: 0, job: null, local: 0, subs: new Set() };
function limitPing() { limitMem.subs.forEach((fn) => { try { fn(); } catch {} }); }
export function limitKeep(uid, data) {
  limitMem.uid = uid;
  limitMem.data = data;
  writeJsonLs(`zchat-spend-limit-${uid}`, data);
  limitPing();
}
export function limitWarm(uid) {
  if (!uid || limitMem.uid === uid) return;
  Object.assign(limitMem, { uid, data: readJsonLs(`zchat-spend-limit-${uid}`, null), at: 0, job: null, local: 0 });
}
export function limitNorm(row) {
  if (!row || typeof row !== 'object') return null;
  const n = (v) => (v == null ? null : Math.max(0, Math.floor(Number(v) || 0)));
  return { limit: n(row.limit), spent: n(row.spent) || 0, nextSet: !!row.next_set, nextLimit: n(row.next_limit), nextAt: row.next_at || null, resets: row.resets || null, hasPin: !!row.has_pin, lockedUntil: row.locked_until || null };
}
export function loadSpendLimit(uid, force) {
  limitWarm(uid);
  if (!uid) return Promise.resolve(null);
  if (!force && limitMem.data && Date.now() - limitMem.at < 60000) return Promise.resolve(limitMem.data);
  if (limitMem.job) return limitMem.job;
  const started = Date.now();
  limitMem.job = supabase.rpc('zchat_spend_limit', {}).then(({ data, error }) => {
    limitMem.job = null;
    const row = Array.isArray(data) ? data[0] : data;
    if (error || !row) { if (error && rpcMissing(error)) { limitMem.off = true; limitPing(); } return limitMem.data; }
    limitMem.off = false;
    if (limitMem.mark && limitMem.mark > started) return limitMem.data;
    limitMem.local = 0;
    limitMem.at = Date.now();
    limitKeep(uid, limitNorm(row));
    return limitMem.data;
  }, () => { limitMem.job = null; return limitMem.data; });
  return limitMem.job;
}
export function limitLeft(st) { return st && st.limit != null ? Math.max(0, st.limit - st.spent - (limitMem.local || 0)) : null; }
async function spendMonthGate(reason, opts) {
  const o = opts || {};
  const coins = Math.max(0, Math.floor(Number(o.coins) || 0));
  const uid = spendAuthBus.uid;
  if (!coins || !uid || o.force) return true;
  limitWarm(uid);
  const st = limitMem.data;
  if (!st) { loadSpendLimit(uid); return true; }
  if (st.limit == null) return true;
  const left = limitLeft(st);
  const after = () => { limitMem.local += coins; limitMem.mark = Date.now(); limitPing(); setTimeout(() => { limitMem.mark = 0; loadSpendLimit(uid, true); }, 4000); };
  if (coins <= left) { after(); return true; }
  if (!spendAuthBus.show || spendAuthBus.open) return false;
  spendAuthBus.open = true;
  let ok = false;
  try { ok = !!(await spendAuthBus.show({ mode: 'month', reason: String(reason || '').slice(0, 140), coins, left, limit: st.limit, resets: st.resets })); } catch { ok = false; } finally { spendAuthBus.open = false; }
  if (ok) after();
  return ok ? 'pin' : false;
}
function spendLimitError(error) {
  if (!error || error.code !== 'ZL001' || !error.message) return null;
  try { if (limitMem.uid) setTimeout(() => loadSpendLimit(limitMem.uid, true), 300); } catch {}
  return String(error.message).slice(0, 200);
}
export function spendGate(reason, opts) {
  try {
    if (typeof requireSpendAuth === 'function') return spendMonthGate(reason, opts).then((m) => (m === false ? false : Promise.resolve(requireSpendAuth(reason, m === 'pin' ? { ...(opts || {}), okNow: true } : opts)).then((v) => v !== false, () => false)), () => false);
  } catch {}
  return Promise.resolve(true);
}
const shopSubs = new Set();
export function shopPing() { shopSubs.forEach((fn) => { try { fn(); } catch {} }); }
export function useShopTick() {
  const [, setTick] = useState(0);
  useEffect(() => {
    const fn = () => setTick((n) => n + 1);
    shopSubs.add(fn);
    return () => { shopSubs.delete(fn); };
  }, []);
}
export const msMem = { uid: null, data: null, job: null, pend: new Set() };
const wishMem = new Map();
function loadWishlist(uid, force) {
  if (!uid) return Promise.resolve([]);
  const cur = wishMem.get(uid);
  if (!force && cur && cur.list && Date.now() - cur.at < 120000) return Promise.resolve(cur.list);
  if (cur && cur.job) return cur.job;
  const started = Date.now();
  const job = supabase.from('wishlist_items').select('kind, item_key, created_at').eq('user_id', uid).order('created_at', { ascending: false }).limit(60)
    .then(({ data, error }) => {
      const now = wishMem.get(uid);
      if (now && now.mark && now.mark > started) { wishMem.set(uid, { ...now, job: null }); return now.list; }
      const list = !error && Array.isArray(data) ? data.filter((r) => (r.kind === 'set' ? isDecorKey(r.item_key) : r.kind === 'bubble' ? !!CHAR_BUBBLES[r.item_key] : r.kind === 'charm' ? !!CUSTOM_BADGES[r.item_key] : cxKnown(r.kind, r.item_key))) : [];
      wishMem.set(uid, { list, at: Date.now(), off: !!error });
      return list;
    }, () => { wishMem.set(uid, { list: [], at: Date.now(), off: true }); return []; })
    .then((v) => { shopPing(); return v; });
  wishMem.set(uid, { ...(cur || {}), job });
  return job;
}
export function useWishlist(uid) {
  useShopTick();
  useEffect(() => { loadWishlist(uid); }, [uid]);
  const cur = wishMem.get(uid);
  const list = (cur && cur.list) || [];
  const has = (kind, key) => list.some((r) => r.kind === kind && r.item_key === key);
  const toggle = async (kind, key) => {
    const on = has(kind, key);
    const next = on ? list.filter((r) => !(r.kind === kind && r.item_key === key)) : [{ kind, item_key: key, created_at: new Date().toISOString() }, ...list];
    wishMem.set(uid, { list: next, at: Date.now(), mark: Date.now() });
    shopPing();
    hapticTap();
    const { error } = on
      ? await supabase.from('wishlist_items').delete().eq('user_id', uid).eq('kind', kind).eq('item_key', key)
      : await supabase.from('wishlist_items').insert({ user_id: uid, kind, item_key: key });
    if (error) {
      const now = (wishMem.get(uid) || {}).list || next;
      const back = on ? [...list.filter((r) => r.kind === kind && r.item_key === key), ...now.filter((r) => !(r.kind === kind && r.item_key === key))] : now.filter((r) => !(r.kind === kind && r.item_key === key));
      wishMem.set(uid, { list: back, at: Date.now(), mark: Date.now() });
      shopPing();
      return { error: on ? 'Could not remove it. Try again.' : /full/i.test(error.message || '') ? 'Your wishlist is full.' : 'Wishlists switch on once the latest ZChat setup is finished.' };
    }
    return { ok: true, on: !on };
  };
  return { list, has, toggle, off: !!(cur && cur.off) };
}
export const looksMem = { uid: null, list: null, job: null, mark: 0 };
export function collectionStats(rewards) {
  const active = (rewards || []).filter(rewardActive);
  const pick = (kind, ok) => new Set(active.filter((r) => r.kind === kind && ok(r.reward_key)).map((r) => r.reward_key));
  const frames = pick('frame', isDecorKey);
  const plates = pick('nameplate', isDecorKey);
  const effects = new Set(DECOR_ALL.filter((s) => decorOwned(rewards, s.key).effect).map((s) => s.key));
  const bubbles = pick('bubble', (k) => !!CHAR_BUBBLES[k]);
  const charms = pick('charm', (k) => !!CUSTOM_BADGES[k]);
  const styles = pick('namestyle', (k) => !!NAME_STYLES[k]);
  const themes = pick('theme', (k) => !!PROFILE_THEMES[k]);
  const supers = pick('reaction', (k) => cxKnown('reaction', k));
  const fullSets = DECOR_ALL.filter((s) => frames.has(s.key) && plates.has(s.key) && effects.has(s.key)).length;
  const owned = frames.size + plates.size + effects.size + bubbles.size + charms.size + styles.size + themes.size + supers.size;
  const total = DECOR_ALL.length * 3 + CHAR_BUBBLE_KEYS.length + Object.keys(CUSTOM_BADGES).length + (cxFlag.on ? NS_KEYS.length + THEME_KEYS.length + SUPER_KEYS.length - SUPER_FREE.length : 0);
  return { owned, total, frames, plates, effects, bubbles, charms, styles, themes, supers, fullSets, pct: total ? Math.min(100, Math.floor((owned / total) * 100)) : 0 };
}

export const CL = { bg: '#0B0B0F', card: '#15151A', card2: '#1E1E25', thumb: '#33333C', line: 'rgba(255,255,255,0.07)', ink: '#F4F4F6', ink2: 'rgba(235,235,245,0.62)', ink3: 'rgba(235,235,245,0.38)', accent: '#8B6CFF', own: '#3DD68C', gold: '#F5B829' };

