export const NS_OWN_ITEM = { label: 'Custom', rarity: 'legendary', price: 600, about: 'Pick two or three colours, a motion and a weight for your name. It is yours to keep and changing it later is free.', solid: ['#1564C9', '#D6C8FF'], own: true };
export const NS_OWN_SAMPLE = 'own:7c5cfc.ff6fae.ffd36b.shimmer.8';
export function nsOwnSaved() { try { const v = localStorage.getItem('zchat-own-style'); return nsOwn(v) ? v : null; } catch { return null; } }
export function siSpec(kind, k) {
  if (kind === 'stickerpack') return SI_STICKER_BY[k] || null;
  if (kind === 'soundpack') return SI_SOUND_BY[k] || null;
  if (kind === 'typing') return SI_TYPING_BY[k] || null;
  if (kind === 'gamekit') return GAME_KIT_BY[k] || null;
  return null;
}
export function siTitle(kind) { return kind === 'stickerpack' ? 'Sticker packs' : kind === 'soundpack' ? 'Sound packs' : kind === 'gamekit' ? 'Game styles' : 'Typing styles'; }
export function siList(kind) { return kind === 'stickerpack' ? SI_STICKER_PACKS : kind === 'soundpack' ? SI_SOUND_PACKS : kind === 'gamekit' ? GAME_KITS : SI_TYPING; }
export function siOwns(rewards, kind, k) { return (rewards || []).some((r) => r.kind === kind && r.reward_key === k && rewardActive(r)); }
export function SiItemArt({ kind, k, me, size, dark = true }) {
  if (kind === 'stickerpack') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><img src={`/ps-${k}-hi.webp`} alt="" draggable={false} style={{ width: Math.round(size * 0.86), height: Math.round(size * 0.86), objectFit: 'contain', display: 'block' }} /></div>;
  if (kind === 'soundpack') return <SoundPackArt k={k} size={size} />;
  if (kind === 'typing') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><TypingStyleBubble k={k} who={me} dark={dark} scale={Math.max(0.8, Math.min(1.4, size / 90))} /></div>;
  if (kind === 'gamekit') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><GameKitArt k={k} size={Math.round(size * 0.9)} /></div>;
  return null;
}
function bubbleThumb(k, size) {
  return <img src={bubbleArtUri(k)} alt="" draggable={false} style={{ width: size, height: size, objectFit: 'contain', display: 'block' }} />;
}
export function ShopItemArt({ kind, k, me, size, dark }) {
  if (SI_KINDS.includes(kind)) return <SiItemArt kind={kind} k={k} me={me} size={size} dark={dark !== false} />;
  if (kind === 'wallpaper') return <LiveWallArt k={k} size={size} dark={dark !== false} />;
  if (CX_KINDS.includes(kind)) return <CxArt kind={kind} k={k} me={me} size={size} dark={dark} />;
  if (kind === 'set') return <DecorFrameBadge setKey={k} size={size} photo={me.avatar} name={me.name} lazy />;
  if (kind === 'bubble') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{bubbleThumb(k, Math.round(size * 0.82))}</div>;
  return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><CharmPreview charm={k} size={Math.round(size * 0.6)} /></div>;
}
export function shopItemName(kind, k) {
  if (SI_KINDS.includes(kind)) return siSpec(kind, k) ? siSpec(kind, k).label : k;
  if (kind === 'wallpaper') return LIVE_WALL_BY[k] ? LIVE_WALL_BY[k].label : k;
  if (CX_KINDS.includes(kind)) return cxSpec(kind, k) ? cxSpec(kind, k).label : k;
  if (kind === 'set') return DECOR_BY_KEY[k] ? DECOR_BY_KEY[k].name : k;
  if (kind === 'bubble') return CHAR_BUBBLES[k] ? CHAR_BUBBLES[k].label : k;
  return CUSTOM_BADGES[k] ? CUSTOM_BADGES[k].label.replace(/ charm$/i, '') : k;
}
function shopKindTitle(kind) {
  if (SI_KINDS.includes(kind)) return siTitle(kind);
  if (kind === 'wallpaper') return 'Live wallpapers';
  if (kind === 'set') return 'Sets';
  if (kind === 'bubble') return 'Bubbles';
  if (kind === 'charm') return 'Charms';
  if (kind === 'namestyle') return 'Name styles';
  if (kind === 'theme') return 'Profile themes';
  return 'Super reactions';
}

export function ShopBagIcon({ size = 22, color = 'currentColor', strokeWidth = 1.9 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden="true" style={{ flexShrink: 0, display: 'block' }}>
      <path d="M5.2 8.2h13.6l-1 10.4a2.2 2.2 0 0 1-2.2 2H8.4a2.2 2.2 0 0 1-2.2-2z" stroke={color} strokeWidth={strokeWidth} strokeLinejoin="round" />
      <path d="M8.8 10.4V7.2a3.2 3.2 0 0 1 6.4 0v3.2" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" />
    </svg>
  );
}

export const CX_KINDS = ['namestyle', 'theme', 'reaction'];
export function cxKnown(kind, key) {
  if (kind === 'namestyle') return !!NAME_STYLES[key] || key === 'own';
  if (kind === 'theme') return !!PROFILE_THEMES[key];
  if (kind === 'reaction') return !!SUPER_REACTS[key] && !SUPER_REACTS[key].free;
  return false;
}
export function cxSpec(kind, key) {
  if (kind === 'namestyle') return NAME_STYLES[key] || (key === 'own' ? NS_OWN_ITEM : null);
  if (kind === 'theme') return PROFILE_THEMES[key] || null;
  if (kind === 'reaction') return SUPER_REACTS[key] || null;
  return null;
}
export function cxWord(kind) { return kind === 'namestyle' ? 'name style' : kind === 'theme' ? 'theme' : 'super reaction'; }
export function cxOwns(rewards, kind, key, forever) {
  if (kind === 'reaction' && SUPER_REACTS[key] && SUPER_REACTS[key].free) return true;
  return (rewards || []).some((r) => r.kind === kind && r.reward_key === key && rewardActive(r) && (!forever || !r.expires_at));
}
export function NameStyleArt({ k, name, size = 18, dark = true, width }) {
  const shown = String(name || 'You').trim() || 'You';
  const fs = Math.max(11, Math.min(size, ((width || 140) * 1.45) / Math.max(4, shown.length)));
  const kk = k === 'own' ? (nsOwnSaved() || NS_OWN_SAMPLE) : k;
  return <div style={{ maxWidth: '100%', fontSize: fs, fontWeight: 800, letterSpacing: '-0.015em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: dark ? '#F4F4F6' : '#111113', ...NS_ROOM }}><StyledName name={shown} k={kk} dark={dark} /></div>;
}
export function ThemeArt({ k, me, w, h, dark = true, live = true, radius = 14, covered = false }) {
  const name = (me && (me.name || me.username)) || 'You';
  const inkBar = dark ? 'rgba(255,255,255,0.86)' : 'rgba(17,17,19,0.78)';
  const bar2 = dark ? 'rgba(255,255,255,0.42)' : 'rgba(17,17,19,0.34)';
  const page = dark ? '#0C0C0E' : '#FFFFFF';
  const a = Math.round(Math.min(w, h) * 0.3);
  return (
    <div style={{ position: 'relative', width: w, height: h, borderRadius: radius, overflow: 'hidden', background: page, flexShrink: 0, isolation: 'isolate' }}>
      <div style={{ position: 'absolute', inset: 0, background: themeFallback(k, dark), WebkitMaskImage: 'linear-gradient(180deg, #000 0%, #000 62%, rgba(0,0,0,0.45) 84%, rgba(0,0,0,0.2) 100%)', maskImage: 'linear-gradient(180deg, #000 0%, #000 62%, rgba(0,0,0,0.45) 84%, rgba(0,0,0,0.2) 100%)' }}>
        <ThemeCanvas k={k} dark={dark} small fps={15} still={!live || reducedMotion()} covered={covered} />
      </div>
      <div style={{ position: 'absolute', left: Math.round(w * 0.1), top: Math.round(h * 0.2), width: a, height: a, borderRadius: '50%', boxShadow: `0 0 0 2px ${page}`, overflow: 'hidden' }}><Avatar emoji={me && me.avatar} name={name} size={a} /></div>
      <div style={{ position: 'absolute', left: Math.round(w * 0.1), top: Math.round(h * 0.2) + a + Math.round(h * 0.06), width: Math.round(w * 0.46), height: Math.max(4, Math.round(h * 0.035)), borderRadius: 3, background: inkBar }} />
      <div style={{ position: 'absolute', left: Math.round(w * 0.1), top: Math.round(h * 0.2) + a + Math.round(h * 0.06) + Math.max(4, Math.round(h * 0.035)) + Math.round(h * 0.03), width: Math.round(w * 0.3), height: Math.max(3, Math.round(h * 0.026)), borderRadius: 3, background: bar2 }} />
    </div>
  );
}
export function CxArt({ kind, k, me, size, dark = true }) {
  if (kind === 'namestyle') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden' }}><NameStyleArt k={k} name={me && me.name} size={Math.round(size * 0.28)} width={size} dark={dark} /></div>;
  if (kind === 'theme') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><ThemeArt k={k} me={me} w={Math.round(size * 0.74)} h={size} dark={dark} radius={12} live={false} /></div>;
  if (kind === 'reaction') return <div style={{ width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><SuperFace k={k} size={Math.round(size * 0.78)} dark={dark} /></div>;
  return null;
}
export function CxTile({ kind, k, me, status, tone, on, onOpen, cols = 2, covered = false, edition = null }) {
  const spec = cxSpec(kind, k);
  if (!spec) return null;
  const label = spec.label;
  return (
    <div role="button" aria-label={`${label} ${cxWord(kind)}${status ? `, ${tone === 'coin' ? `${status} coins` : status}` : ''}${edition ? `, number ${Math.floor(edition).toLocaleString()}` : ''}`} onClick={onOpen} className="zchat-press"
      style={{ position: 'relative', minWidth: 0, borderRadius: 18, padding: kind === 'theme' ? '8px 8px 11px' : kind === 'reaction' ? '14px 6px 11px' : '18px 12px 12px', cursor: 'pointer', background: CL.card, boxShadow: `inset 0 0 0 ${on ? 2 : 1}px ${on ? CL.accent : CL.line}`, display: 'flex', flexDirection: 'column', alignItems: kind === 'namestyle' ? 'stretch' : 'center' }}>
      {edition ? <EditionTag n={edition} size={11} style={{ position: 'absolute', top: 14, right: 14, zIndex: 2, padding: '3px 6px', borderRadius: 8, background: 'rgba(11,11,15,0.62)' }} /> : null}
      {kind === 'namestyle' && <div style={{ minHeight: 40, display: 'flex', alignItems: 'center', minWidth: 0 }}><NameStyleArt k={k} name={me && me.name} size={19} width={cols >= 3 ? 110 : 150} /></div>}
      {kind === 'theme' && <PtTileArt k={k} me={me} covered={covered} />}
      {kind === 'reaction' && <div style={{ height: 58, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><SuperFace k={k} size={52} dark /></div>}
      <div style={{ alignSelf: 'stretch', display: 'flex', alignItems: kind === 'theme' ? 'flex-start' : 'center', justifyContent: kind === 'reaction' ? 'space-between' : 'flex-start', flex: kind === 'reaction' ? 1 : 'none', gap: kind === 'theme' ? 3 : 6, minWidth: 0, marginTop: kind === 'namestyle' ? 10 : 8, padding: kind === 'theme' ? '0 4px' : 0, flexDirection: kind === 'namestyle' ? 'row' : 'column' }}>
        <span style={{ flex: kind === 'namestyle' ? 1 : 'none', minWidth: 0, maxWidth: '100%', fontSize: kind === 'reaction' ? 13 : 14, fontWeight: 600, color: CL.ink, overflow: 'hidden', textAlign: kind === 'reaction' ? 'center' : 'left', ...(kind === 'reaction' ? { lineHeight: 1.25, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' } : { whiteSpace: 'nowrap', textOverflow: 'ellipsis' }) }}>{label}</span>
        {tone === 'coin'
          ? <CollPrice price={Number(status)} size={kind === 'reaction' ? 12.5 : 13} />
          : status ? <span style={{ fontSize: 12.5, fontWeight: 600, color: tone === 'use' ? '#6FB0F7' : tone === 'own' ? CL.own : CL.gold, flexShrink: 0 }}>{status}</span> : null}
      </div>
    </div>
  );
}
function PtTileArt({ k, me, covered }) {
  const ref = useRef(null);
  const w = useWidthOf(ref, 150);
  return <div ref={ref} style={{ alignSelf: 'stretch' }}><ThemeArt k={k} me={me} w={Math.max(80, w)} h={Math.round(Math.max(80, w) * 1.18)} covered={covered} /></div>;
}
function CxShopSections({ me, rewards, free, onOpen, mode = 'shop', covered = false }) {
  const ownedNs = NS_KEYS.filter((k) => cxOwns(rewards, 'namestyle', k, mode === 'shop'));
  const ownedTh = THEME_KEYS.filter((k) => cxOwns(rewards, 'theme', k, mode === 'shop'));
  const ownedRx = SUPER_KEYS.filter((k) => cxOwns(rewards, 'reaction', k, mode === 'shop'));
  const rank = (kind) => (a, b) => (STORE_RARITY_ORDER[cxSpec(kind, b).rarity] ?? 9) - (STORE_RARITY_ORDER[cxSpec(kind, a).rarity] ?? 9) || (cxSpec(kind, a).price || 0) - (cxSpec(kind, b).price || 0);
  const shopList = (kind, keys, owned) => (mode === 'shop' ? keys.filter((k) => !owned.includes(k) && cxKnown(kind, k)) : owned).slice().sort(mode === 'shop' ? rank(kind) : () => 0);
  const ns = shopList('namestyle', NS_KEYS, ownedNs);
  const th = shopList('theme', THEME_KEYS, ownedTh);
  const rx = mode === 'shop' ? shopList('reaction', SUPER_KEYS, ownedRx) : [...SUPER_FREE, ...ownedRx.filter((k) => !SUPER_REACTS[k].free)];
  const wearNs = cxNs(me);
  const wearTh = ptKeyOf(me);
  const status = (kind, k) => {
    if (mode === 'shop') return [String(shopPrice(kind, k) || 0), 'coin'];
    if (kind === 'namestyle' && wearNs === k) return ['In use', 'use'];
    if (kind === 'theme' && wearTh === k) return ['In use', 'use'];
    if (kind === 'reaction' && SUPER_REACTS[k].free) return ['Free', 'free'];
    const rw = (rewards || []).find((r) => r.kind === kind && r.reward_key === k && rewardActive(r));
    const left = rw ? daysLeft(rw) : null;
    return [left != null ? `${left} ${left === 1 ? 'day' : 'days'} left` : 'Yours', 'own'];
  };
  const grid = (kind, keys, cols) => (
    <div style={{ display: 'grid', gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`, gap: 10 }}>
      {keys.map((k) => { const [st, tone] = status(kind, k); return <CxTile key={k} kind={kind} k={k} me={me} status={st} tone={tone} on={tone === 'use'} cols={cols} covered={covered} onOpen={() => onOpen(kind, k)} />; })}
    </div>
  );
  const none = (text) => <div style={{ fontSize: 13.5, color: CL.ink2, lineHeight: 1.5, padding: '2px 2px 4px' }}>{text}</div>;
  return (
    <>
      <CollSection title="Name styles" sub={mode === 'shop' ? 'Your name, drawn your way, wherever it shows' : 'Everyone sees the one you wear'}>
        {ns.length ? grid('namestyle', ns, 2) : none(mode === 'shop' ? 'Every name style is yours. Switch them in your Collection.' : 'No name styles yet. You can find them in the Shop.')}
      </CollSection>
      <CollSection title="Profile themes" sub={mode === 'shop' ? 'A moving scene behind your profile' : 'Shows behind your profile for everyone who visits'}>
        {th.length ? grid('theme', th, 2) : none(mode === 'shop' ? 'Every theme is yours. Switch them in your Collection.' : 'No themes yet. You can find them in the Shop.')}
      </CollSection>
      <CollSection title="Super reactions" sub={mode === 'shop' ? (free ? `Big reactions that play over the chat. ${SUPER_FREE_WORD} are free for everyone.` : 'Big reactions that play over the chat') : 'Hold a message and pick one from the top row'}>
        {rx.length ? grid('reaction', rx, 3) : none('Every super reaction is yours. Hold a message to send one.')}
      </CollSection>
    </>
  );
}
let siCssOn = false;
export function siCss() {
  if (siCssOn || typeof document === 'undefined') return;
  siCssOn = true;
  try {
    const el = document.createElement('style');
    el.setAttribute('data-zsi', '1');
    el.textContent = [
      '.zsi-glow .zsi-ga,.zsi-glow .zsi-gb{border-radius:50%;animation:zsi-glow 3.2s ease-in-out infinite}',
      '.zsi-glow .zsi-ga{--gc:var(--ga)}.zsi-glow .zsi-gb{--gc:var(--gb)}',
      '@keyframes zsi-glow{0%,100%{filter:drop-shadow(0 0 0 rgba(0,0,0,0))}50%{filter:drop-shadow(0 0 10px var(--gc))}}',
      '@keyframes zsi-ring{0%,100%{box-shadow:0 0 0 2px var(--gc),0 0 0 0 var(--gc)}50%{box-shadow:0 0 0 2px var(--gc),0 0 12px 2px var(--gc)}}',
      '.zsi-ringglow{border-radius:50%;animation:zsi-ring 3.2s ease-in-out infinite}',
      '@media (prefers-reduced-motion: reduce){.zsi-glow .zsi-ga,.zsi-glow .zsi-gb,.zsi-ringglow{animation:none}}',
    ].join('\n');
    document.head.appendChild(el);
  } catch {}
}

export function giftOpenStore(uid) {
  const k = `zchat-gift-open-${uid}`;
  const read = () => { try { const v = JSON.parse(localStorage.getItem(k) || '[]'); return Array.isArray(v) ? v : []; } catch { return []; } };
  const add = (id) => { try { const v = read().filter((x) => x !== id); v.push(id); localStorage.setItem(k, JSON.stringify(v.slice(-200))); } catch {} };
  return { read, add };
}
function giftSince(uid) {
  const k = `zchat-gift-since-${uid}`;
  try {
    const v = localStorage.getItem(k);
    if (v) return v;
    const now = new Date().toISOString();
    localStorage.setItem(k, now);
    return now;
  } catch { return new Date().toISOString(); }
}
export function giftOfNote(n) {
  const m = n && n.meta && typeof n.meta === 'object' ? n.meta : {};
  if (Number(m.coins) > 0) return { kind: 'coins', coins: Math.floor(Number(m.coins)) };
  const coinText = /^(\d+) coins/.exec(String((n && n.text) || ''));
  if (coinText && !m.key) return { kind: 'coins', coins: Number(coinText[1]) };
  if (m.key && (m.kind === 'set' || m.kind === 'frame' || m.kind === 'nameplate' || m.kind === 'effect') && isDecorKey(m.key)) return { kind: m.kind, key: m.key };
  if (m.key && m.kind === 'bubble' && CHAR_BUBBLES[m.key]) return { kind: 'bubble', key: m.key };
  if (m.key && m.kind === 'charm' && CUSTOM_BADGES[m.key]) return { kind: 'charm', key: m.key };
  if (m.key && CX_KINDS.includes(m.kind) && cxSpec(m.kind, m.key)) return { kind: m.kind, key: m.key };
  if (m.kind === 'verified' && VERIFIED_TIERS[m.key || 'blue']) return { kind: 'verified', key: m.key || 'blue', days: Number(m.days) || 30, until: m.until || null };
  if (m.key && SI_KINDS.includes(m.kind) && siSpec(m.kind, m.key)) return { kind: m.kind, key: m.key };
  return null;
}
export function giftNoteText(n) {
  const t = String((n && n.text) || '');
  const m = /, "(.*)"$/.exec(t);
  return m ? m[1] : '';
}
function useGiftInbox(uid) {
  const [list, setList] = useState([]);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    if (!uid) return undefined;
    let alive = true;
    const since = giftSince(uid);
    const load = async () => {
      const { data, error } = await supabase.from('notifications').select('id, actor_id, kind, text, meta, created_at').eq('user_id', uid).eq('kind', 'gift').gt('created_at', since).order('created_at', { ascending: true }).limit(20);
      if (!alive || error) return;
      const opened = new Set(giftOpenStore(uid).read());
      const rows = (data || []).filter((n) => !opened.has(n.id) && giftOfNote(n));
      const ids = [...new Set(rows.map((n) => n.actor_id).filter(Boolean))];
      let people = [];
      if (ids.length) {
        const r = await supabase.from('profiles').select('id, name, username, avatar, verified, custom_badge').in('id', ids);
        people = r.data || [];
      }
      if (!alive) return;
      setList(rows.map((n) => ({ id: n.id, gift: giftOfNote(n), note: giftNoteText(n), from: people.find((p) => p.id === n.actor_id) || null, at: n.created_at, meta: n.meta || null })));
    };
    load();
    const addLive = async (n) => {
      const g = giftOfNote(n);
      if (!g || !n.id || giftOpenStore(uid).read().includes(n.id)) return false;
      let from = n.actor_id ? gfCardMem.people.get(n.actor_id) || null : null;
      if (n.actor_id && !from) {
        const r = await supabase.from('profiles').select('id, name, username, avatar, verified, custom_badge').eq('id', n.actor_id).maybeSingle();
        from = (r && r.data) || null;
        if (from) gfCardMem.people.set(from.id, from);
      }
      if (!alive) return true;
      setList((prev) => (prev.some((x) => x.id === n.id) ? prev : [...prev, { id: n.id, gift: g, note: giftNoteText(n), from, at: n.created_at, meta: n.meta || null, live: true }]));
      return true;
    };
    const keep = rtKeep(() => supabase.channel(rtName(`gifts-${uid}`))
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `user_id=eq.${uid}` }, (payload) => { if (payload.new && payload.new.kind === 'gift') addLive(payload.new).then((ok) => { if (!ok) setTimeout(load, 400); }, () => setTimeout(load, 400)); }));
    const onVis = () => { if (document.visibilityState === 'visible') load(); };
    document.addEventListener('visibilitychange', onVis);
    return () => { alive = false; document.removeEventListener('visibilitychange', onVis); rtDrop(keep); };
  }, [uid, tick]);
  const opened = (id) => {
    giftOpenStore(uid).add(id);
    setList((prev) => prev.filter((g) => g.id !== id));
  };
  return { list, opened, reload: () => setTick((n) => n + 1) };
}

function AskCoinsCard({ d, isMe, name, onPay }) {
  const { theme } = useTheme();
  const n = Math.max(1, Math.min(GIFT_MAX, Math.floor(Number(d.n) || 0)));
  return (
    <div style={{ width: 236, borderRadius: 18, overflow: 'hidden', background: theme.dark ? '#1C1A24' : '#FFFFFF', boxShadow: `inset 0 0 0 1px ${theme.border}`, color: theme.ink }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '14px 14px 10px' }}>
        <div style={{ width: 46, height: 46, borderRadius: 23, background: 'radial-gradient(circle at 35% 30%, #FFE7A3 0%, #F5B829 70%)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}><CoinIcon size={30} /></div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 22, fontWeight: 800, letterSpacing: '-0.01em', fontVariantNumeric: 'tabular-nums' }}>{formatCount(n)}</div>
          <div style={{ fontSize: 12.5, color: theme.muted }}>{isMe ? 'You asked for coins' : `${name || 'They'} asked for coins`}</div>
        </div>
      </div>
      {d.t && <div style={{ padding: '0 14px 10px', fontSize: 13.5, lineHeight: 1.4, color: theme.ink2 || theme.ink }}>{d.t}</div>}
      {!isMe && onPay && (
        <div role="button" aria-label={`Send ${coinsText(n)}`} onClick={(e) => { e.stopPropagation(); hapticTap(); onPay(n); }} className="zchat-press"
          style={{ margin: '0 10px 10px', height: 40, borderRadius: 12, background: theme.coral, color: '#FFFFFF', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, fontSize: 14.5, fontWeight: 700, cursor: 'pointer' }}>Send {formatCount(n)} {n === 1 ? 'coin' : 'coins'}</div>
      )}
    </div>
  );
}

export const gfCardMem = { bag: new Map(), chip: new Map(), santa: new Map(), want: { bag: new Set(), chip: new Set(), santa: new Set() }, timer: 0, subs: new Set(), live: null, liveUid: null, seen: 0, people: new Map(), peopleWant: new Set(), peopleTimer: 0 };
const GF_CARD_RPC = { bag: 'zchat_bags', chip: 'zchat_chips', santa: 'zchat_santas' };
function gfCardPing() { gfCardMem.subs.forEach((fn) => { try { fn(); } catch {} }); }
export function gfCardPut(kind, row) {
  if (!row || row.id == null) return;
  gfCardMem[kind].set(String(row.id), row);
  gfCardPing();
}
export function santaPut(row) { gfCardPut('santa', row); }
function gfCardFlush() {
  gfCardMem.timer = 0;
  Object.keys(GF_CARD_RPC).forEach((kind) => {
    const ids = [...gfCardMem.want[kind]].slice(0, 50);
    gfCardMem.want[kind].clear();
    if (!ids.length) return;
    supabase.rpc(GF_CARD_RPC[kind], { p_ids: ids }).then(({ data, error }) => {
      if (error) { ids.forEach((id) => { if (!gfCardMem[kind].has(id)) gfCardMem[kind].set(id, rpcMissing(error) ? 'off' : 'err'); }); gfCardPing(); return; }
      const rows = Array.isArray(data) ? data : [];
      rows.forEach((r) => { if (r && r.id) gfCardMem[kind].set(String(r.id), r); });
      ids.forEach((id) => {
        if (rows.some((r) => r && String(r.id) === id)) return;
        const had = gfCardMem[kind].get(id);
        if (had && typeof had === 'object') return;
        gfCardMem[kind].set(id, false);
        const k = `${kind}:${id}`;
        if (!gfCardMem.retried) gfCardMem.retried = new Set();
        if (!gfCardMem.retried.has(k)) { gfCardMem.retried.add(k); setTimeout(() => gfCardWant(kind, id, true), 1500); }
      });
      gfCardPing();
    }, () => { ids.forEach((id) => { if (!gfCardMem[kind].has(id)) gfCardMem[kind].set(id, 'err'); }); gfCardPing(); });
  });
}
function gfCardWant(kind, id, force) {
  if (!id) return;
  const k = String(id);
  if (!force && gfCardMem[kind].has(k) && gfCardMem[kind].get(k) !== 'err') return;
  gfCardMem.want[kind].add(k);
  if (!gfCardMem.timer) gfCardMem.timer = setTimeout(gfCardFlush, 30);
}
function gfCardLive(uid) {
  if (!uid || gfCardMem.liveUid === uid) return;
  if (gfCardMem.live) rtDrop(gfCardMem.live);
  gfCardMem.liveUid = uid;
  const pend = new Map();
  const later = (kind, id) => { if (!id) return; const k = `${kind}:${id}`; clearTimeout(pend.get(k)); pend.set(k, setTimeout(() => { pend.delete(k); gfCardWant(kind, id, true); }, 120)); };
  const rowOf = (p) => (p && (p.new && Object.keys(p.new).length ? p.new : p.old)) || {};
  const cur = (kind, id) => { const v = id ? gfCardMem[kind].get(String(id)) : null; return v && typeof v === 'object' ? v : null; };
  const on = (kind, col) => (p) => { const id = rowOf(p)[col]; if (id && gfCardMem[kind].has(String(id))) later(kind, id); };
  const bagRow = (p) => {
    const r = rowOf(p);
    if (!r.id) return;
    const b = cur('bag', r.id);
    const f = { opened: r.opened, left: r.left_coins, closed_at: r.closed_at, returned: r.returned, note: r.note, message_id: r.message_id, expires_at: r.expires_at };
    Object.keys(f).forEach((k) => { if (f[k] === undefined) delete f[k]; });
    if (b) gfCardPut('bag', { ...b, ...f });
    else if (p.eventType === 'INSERT' && r.sender_id) gfCardPut('bag', { id: r.id, sender: r.sender_id, to: r.receiver_id || null, group: r.group_id || null, total: r.total, slots: r.slots, share: r.share, opens: [], created_at: r.created_at, ...f });
  };
  const bagOpen = (p) => {
    const r = rowOf(p);
    const b = cur('bag', r.bag_id);
    if (!b) { if (r.bag_id && gfCardMem.bag.has(String(r.bag_id))) later('bag', r.bag_id); return; }
    if (b.opens.some((o) => String(o.u) === String(r.user_id))) return;
    gfCardPut('bag', { ...b, opened: Math.max(b.opened, b.opens.length + 1), opens: [...b.opens, { u: r.user_id, c: r.coins, at: r.created_at }] });
  };
  const chipRow = (p) => {
    const r = rowOf(p);
    const g = cur('chip', r.id);
    if (!g) { on('chip', 'id')(p); return; }
    gfCardPut('chip', { ...g, raised: r.raised != null ? r.raised : g.raised, status: r.status || g.status, done_at: r.done_at !== undefined ? r.done_at : g.done_at, expires_at: r.expires_at || g.expires_at });
  };
  const chipPerson = (p) => {
    const r = rowOf(p);
    const g = cur('chip', r.gift_id);
    if (!g) { on('chip', 'gift_id')(p); return; }
    const has = g.people.some((x) => String(x.u) === String(r.user_id));
    const people = has ? g.people.map((x) => (String(x.u) === String(r.user_id) ? { ...x, c: r.coins, at: r.paid_at } : x)) : [...g.people, { u: r.user_id, c: r.coins || 0, at: r.paid_at || null }];
    gfCardPut('chip', { ...g, people });
  };
  const santaRow = (p) => {
    const r = rowOf(p);
    const e = cur('santa', r.id);
    if (!e) { on('santa', 'id')(p); return; }
    if (r.status && r.status !== e.status && (r.status === 'drawn' || r.status === 'revealed')) { gfCardPut('santa', { ...e, status: r.status }); later('santa', r.id); return; }
    gfCardPut('santa', { ...e, status: r.status || e.status, join_until: r.join_until || e.join_until, reveal_at: r.reveal_at || e.reveal_at, note: r.note !== undefined ? r.note : e.note, picked: r.picked != null ? r.picked : e.picked });
  };
  const santaPerson = (p) => {
    const r = rowOf(p);
    const e = cur('santa', r.event_id);
    if (!e) { on('santa', 'event_id')(p); return; }
    const rest = e.people.filter((u) => String(u) !== String(r.user_id));
    gfCardPut('santa', { ...e, people: p.eventType === 'DELETE' ? rest : [...rest, r.user_id] });
  };
  try {
    gfCardMem.live = rtKeep(() => supabase.channel(rtName(`gifts-cards-${uid}`))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'coin_bags' }, bagRow)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'coin_bag_opens' }, bagOpen)
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'group_gifts' }, chipRow)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'group_gift_people' }, chipPerson)
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'santa_events' }, santaRow)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'santa_people' }, santaPerson));
  } catch { gfCardMem.live = null; }
  rtOnRefresh(() => Object.keys(GF_CARD_RPC).forEach((kind) => [...gfCardMem[kind].keys()].slice(-30).forEach((id) => gfCardWant(kind, id, true))));
}
function useGfCard(kind, id, myId) {
  const [, setTick] = useState(0);
  useEffect(() => {
    const fn = () => setTick((n) => n + 1);
    gfCardMem.subs.add(fn);
    gfCardLive(myId);
    gfCardWant(kind, id);
    const onVis = () => { if (document.visibilityState === 'visible') gfCardWant(kind, id, true); };
    document.addEventListener('visibilitychange', onVis);
    return () => { gfCardMem.subs.delete(fn); document.removeEventListener('visibilitychange', onVis); };
  }, [kind, id, myId]);
  return id ? gfCardMem[kind].get(String(id)) : null;
}
function gfPeopleFlush() {
  gfCardMem.peopleTimer = 0;
  const ids = [...gfCardMem.peopleWant].slice(0, 60);
  gfCardMem.peopleWant.clear();
  if (!ids.length) return;
  supabase.from('profiles').select('id, name, username, avatar, avatar_frame, nameplate, verified, verified_until, custom_badge, name_style, profile_theme, is_bot, is_deleted').in('id', ids).then(({ data }) => {
    (data || []).forEach((p) => gfCardMem.people.set(p.id, p));
    gfCardPing();
  }, () => {});
}
export function useGfPeople(ids) {
  const [, setTick] = useState(0);
  const key = (ids || []).filter(Boolean).join(',');
  useEffect(() => {
    const fn = () => setTick((n) => n + 1);
    gfCardMem.subs.add(fn);
    (ids || []).filter(Boolean).forEach((id) => { if (!gfCardMem.people.has(id)) gfCardMem.peopleWant.add(id); });
    if (gfCardMem.peopleWant.size && !gfCardMem.peopleTimer) gfCardMem.peopleTimer = setTimeout(gfPeopleFlush, 40);
    return () => { gfCardMem.subs.delete(fn); };
  }, [key]);
  return (ids || []).map((id) => gfCardMem.people.get(id) || null);
}
