  const sender = b ? String(b.sender) === String(myId) : isMe;
  const closed = !!b && (!!b.closed_at || Date.parse(b.expires_at) <= Date.now());
  const full = !!b && b.opened >= b.slots;
  const canOpen = !!b && !sender && !mine && !closed && !full;
  const open = async () => {
    if (busy || !canOpen) return;
    const guess = b.opened + 1 >= b.slots ? b.left : b.share;
    setBusy(true);
    hapticTap();
    playUiSound('like');
    setBurst(guess);
    gfCardPut('bag', { ...b, opened: b.opened + 1, left: Math.max(0, b.left - guess), opens: [...b.opens, { u: myId, c: guess, at: new Date().toISOString() }] });
    walletPatch(myId, { coins: guess });
    const r = await giftRpc('zchat_bag_open', { p_bag: b.id }, 'Gift bag');
    setBusy(false);
    if (r.error) {
      walletPatch(myId, { coins: -guess });
      gfCardPut('bag', r.row && r.row.bag ? r.row.bag : b);
      setBurst(0);
      appSnack(r.error);
      return;
    }
    gfCardPut('bag', r.row.bag);
    if (Number(r.row.coins) !== guess) { walletPatch(myId, { coins: Number(r.row.coins) - guess }); setBurst(Number(r.row.coins)); }
    if (walletMem.uid === myId && walletMem.data && walletMem.data.ready && r.row.balance != null) { walletKeep(myId, { ...walletMem.data, coins: Math.max(0, Math.floor(Number(r.row.balance))) }); walletMem.mark = Date.now(); walletShow(); }
    playUiSound('win');
  };
