    const r = await giftRpc('zchat_santa_join', { p_event: e.id, p_on: on }, 'Secret Santa');
    setBusy(false);
    if (r.error) { gfCardPut('santa', (r.row && r.row.event) || before); appSnack(r.error); return; }
    gfCardPut('santa', r.row.event);
