    if (back) walletPatch(myId, { coins: back });
    const r = await giftRpc('zchat_santa_cancel', { p_event: e.id }, 'Secret Santa');
    if (r.error) { gfCardPut('santa', before); if (back) walletPatch(myId, { coins: -back }); appSnack(r.error); return; }
