const toolStatusMem = { ai: null, at: 0, job: null };
function aiToolsKnown() {
  if (toolStatusMem.ai !== null && Date.now() - toolStatusMem.at < 12 * 3600000) return toolStatusMem.ai;
  try {
    const o = JSON.parse(localStorage.getItem('zchat-tools-status') || 'null');
    if (o && typeof o.ai === 'boolean' && Date.now() - Number(o.at || 0) < (o.ai ? 12 : 1) * 3600000) { toolStatusMem.ai = o.ai; toolStatusMem.at = Number(o.at); return o.ai; }
  } catch {}
  return null;
}
function aiToolsCheck() {
  const known = aiToolsKnown();
  if (known !== null) return Promise.resolve(known);
  if (toolStatusMem.job) return toolStatusMem.job;
  toolStatusMem.job = zchatTools('status', {}, 8000).then((r) => {
    const gone = !!r && [400, 404, 405, 503].includes(r.status);
    if (!(r && r.data) && !gone) return null;
    const ai = !gone && !!(r.data.ai || r.data.ollama);
    toolStatusMem.ai = ai;
    toolStatusMem.at = Date.now();
    try { localStorage.setItem('zchat-tools-status', JSON.stringify({ ai, at: toolStatusMem.at })); } catch {}
    return ai;
  }, () => null).then((v) => { toolStatusMem.job = null; return v; });
  return toolStatusMem.job;
}
function replyIdeasTarget(profile, group) {
  if (group && group.id) return { k: `g:${group.id}`, body: { groupId: group.id } };
  if (profile && profile.id && !profile.is_bot) return { k: `dm:${profile.id}`, body: { peerId: profile.id } };
  return null;
}
function useReplyIdeas({ myId, profile, group, messages, draft, blocked }) {
  const [open, setOpen] = useState(false);
  const [ai, setAi] = useState(() => aiToolsKnown());
  const target = replyIdeasTarget(profile, group);
  let last = null;
  for (let i = (messages || []).length - 1; i >= 0; i--) {
    const x = messages[i];
    if (!x || x.type === 'system' || x.deleted || String(x.id).startsWith('temp-')) continue;
    last = x;
    break;
  }
  const theirs = !!last && last.sender_id !== myId && !last.bot_reply && !(profile && profile.is_bot);
  const eligible = !!target && theirs && !blocked && !String(draft || '').trim();
  useEffect(() => {
    if (!eligible || ai !== null) return undefined;
    let alive = true;
    aiToolsCheck().then((v) => { if (alive && v !== null) setAi(v); });
    return () => { alive = false; };
  }, [eligible, ai]);
  useEffect(() => { setOpen(false); }, [target && target.k]);
  useEffect(() => { if (String(draft || '').trim()) setOpen(false); }, [draft]);
  const key = target && last ? `${target.k}|${last.id}` : '';
  return { show: eligible && ai === true, open: open && eligible && ai === true, key, target, toggle: () => { hapticTap(); setOpen((v) => !v); }, close: () => setOpen(false) };
}
