    if (people.length) { const { data: ps } = await fetchProfilesView(people); sanitizeAvatarList(ps || [], '').forEach((p) => { if (!p.is_deleted) byId[p.id] = p; }); }
    ids.forEach((pid) => { psTagsMem.set(pid, { at: Date.now(), list: rows.filter((r) => r.post_id === pid && byId[r.user_id]).map((r) => ({ ...r, user: byId[r.user_id] })) }); psTagsPing(pid); });
