        <div role="note" data-ps-ui="1" onClick={(e) => { e.stopPropagation(); setAlt(false); }} className="zchat-pop"
          style={{ position: 'absolute', left: 10, right: 10, bottom: full ? 'calc(26px + env(safe-area-inset-bottom))' : 10, zIndex: 5, display: 'flex', gap: 10, alignItems: 'flex-start', padding: '10px 12px', borderRadius: 12, background: 'rgba(14,14,18,0.86)', color: '#FFFFFF', fontSize: 13.5, lineHeight: 1.45, pointerEvents: 'auto' }}>
          <span style={{ flexShrink: 0, padding: '1px 6px', borderRadius: 5, background: '#FFFFFF', color: '#000000', fontSize: 10.5, fontWeight: 800, marginTop: 1 }}>ALT</span>
          <span style={{ minWidth: 0, wordBreak: 'break-word' }}>{altText}</span>
        </div>
