  if (x.k === 'focus') return `Focus session: ${Math.round(Number(x.d.m) || 0)} min`;
  if (x.k === 'watch') return x.d.t ? `Watch together: ${x.d.t}` : 'Watch together';
  if (x.k === 'listen') return `Listen together: ${listenItemTitle(x.d.q[0])}`;
  if (x.k === 'album') return `Album: ${x.d.t || 'Photos'}`;
  if (x.k === 'pack') return `Sticker pack: ${x.d.n || 'Stickers'}`;
  if (x.k === 'paid') return `Paid message: ${x.d.t}`;
  if (x.k === 'shout') return x.d.n ? `Shoutout for ${x.d.n}` : 'Shoutout';
  if (x.k === 'item') return x.d.t ? `Asked about ${x.d.t}` : 'Shop item';
  if (x.k === 'chan') return `Channel: ${x.d.n || 'Channel'}`;
  if (x.k === 'file') return `File: ${x.d.n || 'File'}`;
  if (x.k === 'snd') return `Sound: ${(SOUNDBOARD.find((s) => s[0] === x.d.k) || SOUNDBOARD[0])[1]}`;
  if (x.k === 'draw') return 'Draw together';
  if (x.k === 'ask') return `Asked for ${coinsText(Number(x.d.n) || 0)}`;
  if (x.k === 'trade') return 'Trade offer';
  if (x.k === 'capsule') return 'Time capsule';
  if (x.k === 'play') return x.d.n === 1 ? 'Added a song to the playlist' : `Added ${x.d.n} songs to the playlist`;
  if (x.k === 'find' || x.k === 'findset') return x.k === 'find' ? `Find a time: ${x.d.t || 'pick your times'}` : x.d.t ? `Picked a time for ${x.d.t}` : 'Picked a time';
