  if (x.k === 'callplan') return x.d.t ? `Planned call: ${x.d.t}` : `Planned ${x.d.k} call`;
  if (x.k === 'bag') return `Coin gift bag, ${coinsText(x.d.n)}`;
  if (x.k === 'chip') return 'Group gift';
  if (x.k === 'santa') return x.d.r ? 'Secret Santa is open' : 'Secret Santa';
  if (x.k === 'cards') return `Flashcards: ${x.d.t}`;
  if (x.k === 'ghm') return `${GAME_TITLES[x.d.m.g] || 'Game'} match`;
  if (x.k === 'ght') return `${GAME_TITLES[x.d.g] || 'Game'} tournament`;
