    const ok = done.filter((d) => !d.res.error && d.res.data);
    const bad = done.filter((d) => d.res.error || !d.res.data);
    ok.forEach((d) => { psTagsMem.delete(post.id); sendPushNotification(d.who.id, 'ZChat', `${(owner && owner.name) || 'Someone'} tagged you in a photo`, `/?post=${post.id}`, owner && owner.avatar); });
