    const { data, error } = await supabase.from('posts').insert({ user_id: userId, media_url: cv.url, media_type: 'image', overlay_url: null, caption: caption || null, kind: 'voice', voice: { u: au.url, d: Math.round(rec.dur * 10) / 10, w: rec.peaks, c: !!coverFile } }).select().single();
