  if (c.hair === 'spiky') parts.push(`<path d="M52 90l2-26 10 8 4-26 12 16 8-26 12 22 10-24 10 22 12-18 4 26 10-8 2 34c-10-20-28-30-48-30s-38 10-48 30z" fill="${hair}"/>`);
