export function avatarSvgUrl(cfg) { return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(avatarSvg(cfg))}`; }

export function loadImageEl(src) {
  return new Promise((res, rej) => { const im = new Image(); im.crossOrigin = 'anonymous'; im.onload = () => res(im); im.onerror = rej; im.src = src; });
}

export function WriteHelpIcon({ size = 20, color = 'currentColor', strokeWidth = 1.8, style }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" style={style} aria-hidden="true">
      <path d="M16.6 3.9a2.2 2.2 0 0 1 3.1 3.1L8.6 18.1l-4.3 1.2 1.2-4.3Z" />
      <path d="M14.6 5.9l3.1 3.1" />
      <path d="M12.5 20.4h7.5" />
    </svg>
  );
}

