  const CONV_LIVE_KEYS = ['wallpaper_a', 'wallpaper_b', 'disappear_secs', 'muted_until_a', 'muted_until_b', 'pinned_by_a', 'pinned_by_b', 'name_bar', 'read_receipts_a', 'read_receipts_b'];
