        const currentMessages = messagesRef.current;
        const pendingMine = currentMessages
          .filter((m) => m.sender_id === session.user.id && !m.deleted && !m.read && m.id != null && !String(m.id).startsWith('temp-') && !m.queued && !m.failed)
