    if (!spec || !me) return;
    const beforeLikes = messageLikes[messageId] || [];
    const mine = beforeLikes.find((r) => r.user_id === session.user.id);
    if (mine && mine.super_key === key) { reactToMessage(messageId, mine.emoji); return; }
    const emoji = spec.base;
    const targetMessage = findMessageById(messageId);
    setMessageLikes((prev) => ({ ...prev, [messageId]: [...(prev[messageId] || []).filter((r) => r.user_id !== session.user.id), { user_id: session.user.id, emoji, super_key: key }] }));
    playUiSound('like');
    superPlay(key, messageId);
