  const myGroupRole = activeGroup ? ((groupMembers.find((gm) => gm.user_id === uid) || {}).role || 'member') : null;
  const myGroupRow = activeGroup ? groupMembers.find((gm) => gm.user_id === uid) : null;
  const myGroupRank = activeGroup ? (myGroupRow ? groupRankOf(activeGroup, myGroupRow) : (activeGroup.created_by === uid ? 3 : -1)) : -1;
  const rolesOnHere = !!activeGroup && groupRolesOn(groupMembers);
  const myGroupMute = activeGroup ? memberMute(myGroupRow) : null;
  const g1 = useG1Chat({ group: activeGroup, uid, rank: myGroupRank, me, members: groupMembers, messages, setMessages, setMembers: setGroupMembers, hold: holdMember, notify: notifyUser, live: !!activeGroup && (isWide || mobileShowChat) });
  const groupCallBlocked = !!activeGroup && !activeGroupCall && (!!myGroupMute || (activeGroup.send_policy === 'admins' && activeGroup.created_by !== session.user.id && groupMembers.some((gm) => gm.user_id === session.user.id && gm.role !== 'admin'))) || (!!activeGroup && !!activeGroup.read_only);
  const [muteTick, setMuteTick] = useState(0);
