                            {g.pinned && <Pin_ size={13} color={theme.coral} />}<span data-zuser="" style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{g.__label || g.name}</span>
