                            {c.lastFromMe && c.preview && c.preview.kind !== 'deleted' && c.preview.kind !== 'system' && <StatusTicks status={c.lastQueued ? 'queued' : c.lastMineRead && dmReceiptsOn(c, me, c.otherProfile) ? 'read' : c.lastMineDelivered ? 'delivered' : 'sent'} />}
