function WnEyeMark({ x, y, r = 16 }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r} fill={ART_C.violet} {...ak} />
      <path d={`M${x - r * 0.66} ${y} Q${x} ${y - r * 0.7} ${x + r * 0.66} ${y} Q${x} ${y + r * 0.7} ${x - r * 0.66} ${y} Z`} fill="#FFFFFF" stroke={ART_INK} strokeWidth="2.2" strokeLinejoin="round" />
      <circle cx={x} cy={y} r={r * 0.24} fill={ART_INK} />
      <circle cx={x + r * 0.09} cy={y - r * 0.1} r={r * 0.08} fill="#FFFFFF" />
    </g>
  );
}

function WnStickerCat({ x, y, s = 1, rot = -8 }) {
  const head = 'M22 46 C21 31 33 21 50 21 C67 21 79 31 78 46 C77 57 66 64 50 64 C34 64 23 57 22 46 Z M29 36 L25 12 C24.6 8.5 27 7.6 29.5 9.6 L45 23 L55 23 L70.5 9.6 C73 7.6 75.4 8.5 75 12 L71 36 Z';
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${s}) translate(-50 -37)`}>
      <path d={head} fill="#FFFFFF" stroke={ART_INK} strokeWidth="17" strokeLinejoin="round" />
      <path d={head} fill="#FFFFFF" stroke="#FFFFFF" strokeWidth="11" strokeLinejoin="round" />
      <ArtCatHead eyes="happy" look={[0, 0]} />
    </g>
  );
}

function WnPhotoBubble({ x, y, w = 62, h = 58 }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx="10" fill={ART_C.card} {...ak} />
      <rect x={x + 5} y={y + 5} width={w - 10} height={h - 10} rx="6" fill={ART_C.sky} />
      <path d={`M${x + 5} ${y + h - 18} C${x + 16} ${y + h - 30} ${x + 26} ${y + h - 26} ${x + 33} ${y + h - 21} C${x + 40} ${y + h - 30} ${x + 50} ${y + h - 30} ${x + w - 5} ${y + h - 22} V${y + h - 5} H${x + 5} Z`} fill={ART_C.mint} />
      <circle cx={x + w - 17} cy={y + 17} r="6" fill={ART_C.yellow} />
      <rect x={x + 5} y={y + 5} width={w - 10} height={h - 10} rx="6" fill="none" stroke={ART_INK} strokeWidth="2.2" />
    </g>
  );
}

function WnGroupRow({ x, y, w = 108, a = ART_C.pink, b = ART_C.yellow, mega = false, dot = false }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height="36" rx="11" fill={ART_C.card} {...ak} />
      {mega ? (
        <g>
          <circle cx={x + 19} cy={y + 18} r="11" fill={ART_C.violet} {...ak} strokeWidth="2.4" />
          <path d={`M${x + 13} ${y + 15.5} H${x + 16} L${x + 23} ${y + 11.5} V${y + 24.5} L${x + 16} ${y + 20.5} H${x + 13} Z`} fill="#FFFFFF" />
        </g>
      ) : (
        <g>
          <circle cx={x + 15} cy={y + 15} r="7.5" fill={a} {...ak} strokeWidth="2.2" />
          <circle cx={x + 24} cy={y + 22} r="7.5" fill={b} {...ak} strokeWidth="2.2" />
        </g>
      )}
      <rect x={x + 37} y={y + 10} width={w * 0.4} height="6" rx="3" fill="rgba(43,37,64,0.3)" />
      <rect x={x + 37} y={y + 21} width={w * 0.52} height="5" rx="2.5" fill="rgba(43,37,64,0.15)" />
      {dot && <circle cx={x + w - 13} cy={y + 18} r="4.5" fill={ART_C.violet} />}
    </g>
  );
}

function WnLiveTag({ x, y }) {
  return (
    <g>
      <rect x={x} y={y} width="54" height="24" rx="12" fill={ART_C.coralDeep} {...ak} strokeWidth="2.6" />
      <circle cx={x + 13} cy={y + 12} r="4" fill="#FFFFFF" />
      <text x={x + 34} y={y + 16.5} textAnchor="middle" fontFamily="-apple-system, BlinkMacSystemFont, 'SF Pro Text', Roboto, sans-serif" fontSize="13" fontWeight="800" fill="#FFFFFF">Live</text>
    </g>
  );
}

function WnWaves({ x, y, s = 1 }) {
  const line = useArtLine();
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`} fill="none" stroke={line} strokeLinecap="round">
      <path d="M0 -10 C5 -5 5 5 0 10" strokeWidth="3.4" />
      <path d="M11 -19 C20 -9 20 9 11 19" strokeWidth="3.4" opacity="0.75" />
      <path d="M22 -28 C35 -13 35 13 22 28" strokeWidth="3.4" opacity="0.5" />
    </g>
  );
}

