function WnBoardPin({ x, y, color = ART_C.coral }) {
  return (
    <g>
      <circle cx={x} cy={y} r="5.4" fill={color} {...ak} strokeWidth="2.2" />
      <circle cx={x - 1.6} cy={y - 1.8} r="1.5" fill="#FFFFFF" opacity="0.8" />
    </g>
  );
}

function WnFilmStrip({ x, y, rot = 0 }) {
  const holes = [];
  for (let i = 0; i < 8; i++) {
    holes.push(<rect key={`l${i}`} x={x + 5} y={y + 8 + i * 17} width="7" height="9" rx="2" fill="#FFFFFF" opacity="0.85" />);
    holes.push(<rect key={`r${i}`} x={x + 54} y={y + 8 + i * 17} width="7" height="9" rx="2" fill="#FFFFFF" opacity="0.85" />);
  }
  const frames = [[ART_C.sky, ART_C.mint], [ART_C.pink, ART_C.yellow], [ART_C.lilac, ART_C.blue]];
  return (
    <g transform={`rotate(${rot} ${x + 33} ${y + 74})`}>
      <rect x={x} y={y} width="66" height="148" rx="9" fill={ART_C.night} {...ak} />
      {holes}
      {frames.map(([sky, hill], i) => (
        <g key={i}>
          <rect x={x + 16} y={y + 10 + i * 44} width="34" height="38" rx="4" fill={sky} />
          <path d={`M${x + 16} ${y + 38 + i * 44} C${x + 24} ${y + 30 + i * 44} ${x + 32} ${y + 32 + i * 44} ${x + 36} ${y + 35 + i * 44} C${x + 41} ${y + 29 + i * 44} ${x + 47} ${y + 30 + i * 44} ${x + 50} ${y + 34 + i * 44} V${y + 48 + i * 44} H${x + 16} Z`} fill={hill} />
          <circle cx={x + 26 + i * 6} cy={y + 20 + i * 44} r="4" fill={ART_C.yellow} />
        </g>
      ))}
    </g>
  );
}

