function TicTacToeCard({ state, myId, live, peerName, onMove, onRematch, ink, fresh }) {
  const { theme } = useTheme();
  const myMark = state.x === myId ? 1 : state.o === myId ? 2 : 0;
  const result = state.w ? (state.w === 'd' ? { who: 3, line: null } : (tttWinner(state.b) || { who: state.w === 'x' ? 1 : 2, line: null })) : null;
  const finished = !!result;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (result.who === 3 ? 'draw' : result.who === myMark ? 'win' : 'lose') : null);
  const myTurn = live && !finished && state.t === myId && myMark > 0;
  const winLine = result && result.line ? result.line : [];
  const status = finished
    ? (result.who === 3 ? 'Draw' : result.who === myMark ? 'You won' : `${peerName || 'They'} won`)
    : myTurn ? 'Your move' : live ? 'Their move' : `Move ${state.n}`;
  const mark = (v, size) => <G3Mark v={v} size={size} />;
  const tap = (i) => {
    if (!myTurn || state.b[i]) return;
    const b = state.b.slice();
    b[i] = myMark;
    const w = tttWinner(b);
    hapticTap();
    playUiSound('tap');
    onMove({ ...state, b, t: myMark === 1 ? state.o : state.x, n: (state.n || 0) + 1, w: w ? (w.who === 3 ? 'd' : w.who === 1 ? 'x' : 'o') : null });
  };
  const cell = 56;
  return (
    <GameCardShell k="ttt" width={204} live={live} title="Tic tac toe" status={status} hot={myTurn}>
      <div style={{ ...g3Board(theme.dark ? '#2E2752' : '#DDD6FE', 16), padding: 7, display: 'grid', gridTemplateColumns: `repeat(3, ${cell - 4}px)`, gap: 6, justifyContent: 'center', width: 'fit-content', margin: '0 auto 5px' }}>
        {state.b.map((v, i) => (
          <div key={i} role={myTurn && !v ? 'button' : undefined} aria-label={myTurn && !v ? `Cell ${i + 1}` : undefined} data-silent="1" onClick={() => tap(i)} style={{
            width: cell - 4, height: cell - 4, display: 'flex', alignItems: 'center', justifyContent: 'center',
            ...g3TileStyle(winLine.includes(i) ? '#FDE68A' : (theme.dark ? '#453B78' : '#FFFFFF'), 11, 3), cursor: myTurn && !v ? 'pointer' : 'default',
          }}>{mark(v, Math.round(cell * 0.62))}</div>
        ))}
      </div>
      {live && finished && onRematch && (
        <button onClick={onRematch} className="zchat-gbtn" style={{ marginTop: 10, width: '100%', height: 34, borderRadius: 10, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Play again</button>
      )}
      {live && !finished && !myTurn && myMark > 0 && state.n === 0 && (
        <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>They go first</div>
      )}
      {live && !finished && myTurn && state.n === 0 && (
        <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>You go first. Tap a square</div>
      )}
    </GameCardShell>
  );
}

const TILE_COLORS = { 2: '#EEE4DA', 4: '#EDE0C8', 8: '#F2B179', 16: '#F59563', 32: '#F67C5F', 64: '#F65E3B', 128: '#EDCF72', 256: '#EDCC61', 512: '#EDC850', 1024: '#EDC53F', 2048: '#EDC22E' };
