  const [over, setOver] = useState(false);
  const touch = useRef(null);
  const canMove = (g) => { if (g.includes(0)) return true; for (let i = 0; i < 16; i++) { if (i % 4 < 3 && g[i] === g[i + 1]) return true; if (i < 12 && g[i] === g[i + 4]) return true; } return false; };
