export function readQuiet() {
  try { const q = JSON.parse(localStorage.getItem('zchat-quiet') || 'null'); if (q && typeof q === 'object') return { on: !!q.on, from: Number.isInteger(q.from) ? q.from : 22, to: Number.isInteger(q.to) ? q.to : 7 }; } catch {}
  return { on: false, from: 22, to: 7 };
}
function quietNow() {
  const q = readQuiet();
  if (!q.on) return false;
  const h = new Date().getHours();
  return q.from === q.to ? true : q.from < q.to ? h >= q.from && h < q.to : h >= q.from || h < q.to;
}

const VIBE_OPTIONS = [['default', 'Default'], ['short', 'Short'], ['long', 'Long'], ['double', 'Double'], ['heartbeat', 'Heartbeat'], ['off', 'Off']];
const VIBE_PATTERNS = { default: [220], short: [60], long: [480], double: [90, 110, 90], heartbeat: [70, 110, 150, 600, 70, 110, 150], off: [] };
function canVibrate() {
  try { return typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function' && !isAppleMobile() && !!window.matchMedia && window.matchMedia('(pointer: coarse)').matches; } catch { return false; }
}
function readChatVibes() { const m = readJsonLs('zchat-chat-vibes', {}); return m && typeof m === 'object' && !Array.isArray(m) ? m : {}; }
function chatVibeFor(key) { const v = key ? readChatVibes()[key] : null; return VIBE_PATTERNS[v] ? v : 'default'; }
function vibeLabel(v) { return (VIBE_OPTIONS.find(([k]) => k === v) || VIBE_OPTIONS[0])[1]; }
function vibeNow(kind, preview) {
  if (!canVibrate() || !buzzAllowed() || (kind === 'default' && !preview)) return;
  const p = VIBE_PATTERNS[kind];
  if (!p || !p.length) return;
  try { navigator.vibrate(p); } catch {}
}
function setChatVibe(uid, key, v) {
  const m = { ...readChatVibes() };
  if (!v || v === 'default') delete m[key]; else m[key] = v;
  writeJsonLs('zchat-chat-vibes', m);
  syncAlertPrefs(uid);
}
export const vipNow = { uid: null, ids: new Set() };
export function readVip(uid) { const a = uid ? readJsonLs(`zchat-vip-${uid}`, []) : []; return Array.isArray(a) ? a.filter((p) => p && typeof p.id === 'string').slice(0, 50) : []; }
function loadVip(uid) { vipNow.uid = uid; vipNow.ids = new Set(readVip(uid).map((p) => p.id)); }
function vipHas(id) { return !!id && vipNow.ids.has(id); }
export function syncAlertPrefs(uid) {
  if (!uid) return;
  const vip = readVip(uid).map((p) => p.id);
  const vibes = readChatVibes();
  writeWorkerPref('/__vip', (cur) => ({ ...cur, [uid]: vip }));
  writeWorkerPref('/__vibe', (cur) => ({ ...cur, [uid]: vibes }));
  writeWorkerPref('/__quiet', () => readQuiet());
}

export function readReminders(uid) {
  try { const a = JSON.parse(localStorage.getItem(`zchat-reminders-${uid}`) || '[]'); return Array.isArray(a) ? a.filter((r) => r && r.id && typeof r.at === 'number') : []; } catch { return []; }
}
export function writeReminders(uid, list) {
  try { localStorage.setItem(`zchat-reminders-${uid}`, JSON.stringify(list.slice(-120))); } catch {}
  try { window.dispatchEvent(new Event('zchat-reminders')); } catch {}
}
export function reminderWhen(at) {
  const d = new Date(at);
  const a = new Date(); a.setHours(0, 0, 0, 0);
  const b = new Date(d); b.setHours(0, 0, 0, 0);
  const diff = Math.round((b - a) / 86400000);
  const t = fmtHM(d);
  if (diff === 0) return `Today at ${t}`;
  if (diff === 1) return `Tomorrow at ${t}`;
  if (diff === -1) return `Yesterday at ${t}`;
  return `${fmtDate(d, { weekday: 'short', day: 'numeric', month: 'short' })} at ${t}`;
}
function reminderChoices() {
  const now = Date.now();
  const tonight = new Date(); tonight.setHours(20, 0, 0, 0);
  const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); tomorrow.setHours(9, 0, 0, 0);
  const weekend = new Date(); weekend.setDate(weekend.getDate() + ((6 - weekend.getDay() + 7) % 7 || 7)); weekend.setHours(10, 0, 0, 0);
  const list = [
    { label: 'In 20 minutes', at: now + 20 * 60000 },
    { label: 'In 1 hour', at: now + 3600000 },
    { label: 'In 3 hours', at: now + 3 * 3600000 },
  ];
  if (tonight.getTime() - now > 3600000) list.push({ label: 'Tonight', at: tonight.getTime() });
  list.push({ label: 'Tomorrow morning', at: tomorrow.getTime() });
  list.push({ label: 'This weekend', at: weekend.getTime() });
  return list;
}

