function SkyHopGame({ seed, onDuelFinish } = {}) {
  const { theme } = useTheme();
  const rnd = useGameRng(seed, 'sky');
  const canvasRef = useRef(null);
  const st = useRef(null);
  const [phase, setPhase] = useState('ready');
  const [score, setScore] = useState(0);
  const [best, setBest] = useState(() => readBest('sky'));
  const W = 320;
  const H = 440;
  const GAP = 132;
  const reset = () => { st.current = { y: H / 2, vy: 0, pipes: [], frame: 0, score: 0 }; };
  if (!st.current) reset();
  const draw = () => {
    const c = canvasRef.current; if (!c) return;
    const ctx = gctx(c);
    const s = st.current;
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    sky.addColorStop(0, theme.dark ? '#1B1740' : '#8FD3FF');
    sky.addColorStop(1, theme.dark ? '#3A2A6E' : '#E3F6FF');
    ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = theme.dark ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.7)';
    for (let i = 0; i < 3; i++) { const cx = ((i * 140 + s.frame * 0.4) % (W + 80)) - 40; ctx.beginPath(); ctx.arc(cx, 70 + i * 60, 18, 0, Math.PI * 2); ctx.arc(cx + 20, 64 + i * 60, 22, 0, Math.PI * 2); ctx.arc(cx + 42, 72 + i * 60, 16, 0, Math.PI * 2); ctx.fill(); }
    const pc = theme.dark ? '#6D5BD0' : '#22C55E';
    const pipeG = (x) => { const g = ctx.createLinearGradient(x, 0, x + 46, 0); g.addColorStop(0, g3lt(pc, 0.3)); g.addColorStop(0.35, pc); g.addColorStop(1, g3dk(pc, 0.4)); return g; };
    s.pipes.forEach((p) => {
      ctx.fillStyle = pipeG(p.x);
      roundRectFill(ctx, p.x, -8, 46, p.top + 8, 8); roundRectFill(ctx, p.x, p.top + GAP, 46, H - p.top - GAP - 28 + 8, 8);
      ctx.fillStyle = pipeG(p.x - 4);
      roundRectFill(ctx, p.x - 4, p.top - 14, 54, 14, 5); roundRectFill(ctx, p.x - 4, p.top + GAP, 54, 14, 5);
      ctx.fillStyle = 'rgba(255,255,255,0.35)'; ctx.fillRect(p.x + 6, -8, 4, p.top - 6); ctx.fillRect(p.x + 6, p.top + GAP + 14, 4, Math.max(0, H - p.top - GAP - 42));
    });
    ctx.fillStyle = theme.dark ? '#10335C' : '#D8B37A'; ctx.fillRect(0, H - 28, W, 28);
    ctx.fillStyle = theme.dark ? '#3B2F6E' : '#8BD36B'; ctx.fillRect(0, H - 28, W, 5);
    ctx.save();
    ctx.translate(80, s.y);
    ctx.rotate(Math.max(-0.5, Math.min(0.8, s.vy / 10)));
    g3CanvasBall(ctx, 0, 0, 13, '#FBBF24');
    ctx.fillStyle = '#F97316'; ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(19, 2); ctx.lineTo(10, 6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#C2410C'; ctx.beginPath(); ctx.moveTo(10, 2); ctx.lineTo(19, 2); ctx.lineTo(10, 6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(4, -4, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(5.5, -4, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#F59E0B'; ctx.beginPath(); ctx.ellipse(-4, 3, 7, 4, -0.4, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  };
  useEffect(() => { draw(); });
  useEffect(() => {
    if (phase !== 'playing') return undefined;
    const tick = () => {
      const s = st.current;
      s.frame += 1;
      s.vy = Math.min(9, s.vy + 0.34);
      s.y += s.vy;
      if (s.y < 13) { s.y = 13; s.vy = Math.max(0, s.vy); }
      if (s.frame % 100 === 0) s.pipes.push({ x: W + 10, top: 48 + rnd() * (H - 28 - GAP - 96), passed: false });
      s.pipes.forEach((p) => { p.x -= 2.4; if (!p.passed && p.x + 46 < 80) { p.passed = true; s.score += 1; setScore(s.score); playUiSound('point'); } });
      s.pipes = s.pipes.filter((p) => p.x > -60);
      const hit = s.y + 12 > H - 28 || s.pipes.some((p) => 80 + 11 > p.x && 80 - 11 < p.x + 46 && (s.y - 11 < p.top || s.y + 11 > p.top + GAP));
      if (hit) {
        setPhase('over'); playUiSound('lose'); hapticTap();
        noteSoloScore('sky', s.score);
      const b = readBest('sky');
        if (s.score > b) { setBest(s.score); writeBest('sky', s.score); }
        return false;
      }
      return true;
    };
    return runFixedLoop(tick, draw);
  }, [phase]);
  const flap = () => {
    if (phase !== 'playing') { if (phase === 'over' && onDuelFinish) return; reset(); setScore(0); st.current.vy = -6.2; setPhase('playing'); playUiSound('toggle'); return; }
    st.current.vy = -6.4;
    playUiSound('key');
    hapticTap();
  };
  useEffect(() => {
    const onKey = (e) => { if (e.key === ' ' || e.key === 'ArrowUp') { e.preventDefault(); flap(); } };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 14, paddingTop: 8 }}>
      <GameStats items={[['Score', score], ['Best', best]]} />
      <div onPointerDown={(e) => { e.preventDefault(); flap(); }} style={{ position: 'relative', width: GAME_TALL_W, aspectRatio: '320 / 440', borderRadius: 18, overflow: 'hidden', touchAction: 'none', userSelect: 'none', border: `1px solid ${theme.border}`, cursor: 'pointer', boxShadow: '0 12px 30px rgba(0,0,0,0.25)' }}>
        <canvas ref={canvasRef} width={Math.round(W * GDPR)} height={Math.round(H * GDPR)} style={{ width: '100%', height: '100%', display: 'block' }} />
        {phase !== 'playing' && <GameOverlay {...duelOverlayProps(phase, score, onDuelFinish, flap, 'Sky hop', `You passed ${score}`, 'Tap to flap. Slip through the gaps and do not touch anything.')} />}
      </div>
    </div>
  );
}

function BricksGame({ seed, onDuelFinish } = {}) {
  const { theme } = useTheme();
  const rnd = useGameRng(seed, 'bricks');
  const canvasRef = useRef(null);
  const st = useRef(null);
  const [phase, setPhase] = useState('ready');
  const [score, setScore] = useState(0);
  const [lives, setLives] = useState(3);
  const [level, setLevel] = useState(1);
  const [best, setBest] = useState(() => readBest('bricks'));
  const W = 320;
  const H = 420;
  const PW = 66;
  const PH = 10;
  const BR = 6;
  const COLORS = ['#F87171', '#FB923C', '#FBBF24', '#4ADE80', '#60A5FA'];
  const makeBricks = () => { const out = []; for (let r = 0; r < 5; r++) for (let c = 0; c < 7; c++) out.push({ x: 8 + c * 44, y: 40 + r * 20, w: 40, h: 14, c: COLORS[r], on: true }); return out; };
  const fresh = () => ({ px: W / 2 - PW / 2, bx: W / 2, by: H - 60, vx: 2.3 * (rnd() < 0.5 ? -1 : 1), vy: -3.4, bricks: makeBricks(), score: 0, lives: 3, level: 1, launched: false, speed: 1 });
  if (!st.current) st.current = fresh();
  const draw = () => {
    const c = canvasRef.current; if (!c) return;
    const ctx = gctx(c);
    const s = st.current;
    ctx.fillStyle = theme.dark ? '#140F2A' : '#F3F0FF'; ctx.fillRect(0, 0, W, H);
    s.bricks.forEach((b) => {
      if (!b.on) return;
      ctx.fillStyle = g3dk(b.c, 0.35); roundRectFill(ctx, b.x, b.y + 2, b.w, b.h, 4);
      ctx.fillStyle = b.c; roundRectFill(ctx, b.x, b.y, b.w, b.h - 1, 4);
      ctx.fillStyle = 'rgba(255,255,255,0.38)'; roundRectFill(ctx, b.x + 2, b.y + 1.5, b.w - 4, Math.max(2, b.h * 0.28), 2);
    });
    const pcol = theme.dark ? '#B79CFF' : '#7C5CFC';
    ctx.fillStyle = g3dk(pcol, 0.4); roundRectFill(ctx, s.px, H - 30 + 3, PW, PH, 5);
    const pg = ctx.createLinearGradient(0, H - 30, 0, H - 30 + PH); pg.addColorStop(0, g3lt(pcol, 0.35)); pg.addColorStop(1, pcol);
    ctx.fillStyle = pg; roundRectFill(ctx, s.px, H - 30, PW, PH, 5);
    g3CanvasBall(ctx, s.bx, s.by, BR, theme.dark ? '#F8FAFC' : '#4C1D95');
  };
  useEffect(() => { draw(); });
  useEffect(() => {
    if (phase !== 'playing') return undefined;
    const tick = () => {
      const s = st.current;
      if (!s.launched) { s.bx = s.px + PW / 2; s.by = H - 30 - BR - 1; }
      else {
        s.bx += s.vx * s.speed; s.by += s.vy * s.speed;
        if (s.bx - BR < 0) { s.bx = BR; s.vx = Math.abs(s.vx); }
        if (s.bx + BR > W) { s.bx = W - BR; s.vx = -Math.abs(s.vx); }
        if (s.by - BR < 0) { s.by = BR; s.vy = Math.abs(s.vy); }
        if (s.vy > 0 && s.by + BR >= H - 30 && s.by + BR <= H - 30 + PH + 4 && s.bx >= s.px - BR && s.bx <= s.px + PW + BR) {
          const rel = (s.bx - (s.px + PW / 2)) / (PW / 2);
          const ang = rel * 1.05;
          const sp = Math.hypot(s.vx, s.vy);
          s.vx = Math.sin(ang) * sp; s.vy = -Math.abs(Math.cos(ang) * sp);
          s.by = H - 30 - BR;
          playUiSound('tap');
        }
        for (let i = 0; i < s.bricks.length; i++) {
          const b = s.bricks[i];
          if (!b.on) continue;
          if (s.bx + BR > b.x && s.bx - BR < b.x + b.w && s.by + BR > b.y && s.by - BR < b.y + b.h) {
            b.on = false;
            s.score += 10;
            setScore(s.score);
            playUiSound('point');
            const fromSide = Math.min(Math.abs(s.bx - b.x), Math.abs(s.bx - (b.x + b.w))) < Math.min(Math.abs(s.by - b.y), Math.abs(s.by - (b.y + b.h)));
            if (fromSide) s.vx = -s.vx; else s.vy = -s.vy;
            break;
          }
        }
        if (s.bricks.every((b) => !b.on)) {
          s.level += 1; setLevel(s.level); s.speed = Math.min(1.9, s.speed + 0.15); s.bricks = makeBricks(); s.launched = false; s.vy = -Math.abs(s.vy); playUiSound('win'); hapticTap();
        }
        if (s.by - BR > H) {
          s.lives -= 1; setLives(s.lives); hapticTap(); playUiSound('cancel');
          if (s.lives <= 0) {
            setPhase('over'); playUiSound('lose');
            noteSoloScore('bricks', s.score);
      const b = readBest('bricks');
            if (s.score > b) { setBest(s.score); writeBest('bricks', s.score); }
            return false;
          }
          s.launched = false; s.vx = 2.3 * (rnd() < 0.5 ? -1 : 1); s.vy = -3.4;
        }
      }
      return true;
    };
    return runFixedLoop(tick, draw);
  }, [phase]);
  const start = () => { if (phase === 'over' && onDuelFinish) return; st.current = fresh(); setScore(0); setLives(3); setLevel(1); setPhase('playing'); };
  const moveTo = (clientX, el) => {
    const r = el.getBoundingClientRect();
    const x = ((clientX - r.left) / r.width) * W;
    st.current.px = Math.max(0, Math.min(W - PW, x - PW / 2));
    if (phase !== 'playing') draw();
  };
  const launch = () => { if (phase !== 'playing') { start(); playUiSound('toggle'); return; } if (!st.current.launched) { st.current.launched = true; hapticTap(); playUiSound('key'); } };
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'ArrowLeft') { e.preventDefault(); st.current.px = Math.max(0, st.current.px - 22); }
      else if (e.key === 'ArrowRight') { e.preventDefault(); st.current.px = Math.min(W - PW, st.current.px + 22); }
      else if (e.key === ' ') { e.preventDefault(); launch(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 14, paddingTop: 8 }}>
      <GameStats items={[['Score', score], ['Lives', lives], ['Level', level], ['Best', best]]} />
      <div onPointerMove={(e) => moveTo(e.clientX, e.currentTarget)} onPointerDown={(e) => { moveTo(e.clientX, e.currentTarget); launch(); }} style={{ position: 'relative', width: GAME_BRICKS_W, aspectRatio: '320 / 420', borderRadius: 18, overflow: 'hidden', touchAction: 'none', userSelect: 'none', border: `1px solid ${theme.border}`, cursor: 'pointer', boxShadow: '0 12px 30px rgba(0,0,0,0.25)' }}>
        <canvas ref={canvasRef} width={Math.round(W * GDPR)} height={Math.round(H * GDPR)} style={{ width: '100%', height: '100%', display: 'block' }} />
        {phase !== 'playing' && <GameOverlay {...duelOverlayProps(phase, score, onDuelFinish, start, 'Bricks', `Game over, ${score} points`, 'Slide to move the paddle. Tap to launch the ball and clear every brick.')} />}
      </div>
    </div>
  );
}

const WORD_LIST = 'about above abuse actor acute admit adopt adult after again agent agree ahead alarm album alert alike alive allow alone along alter among anger angle angry apart apple apply arena argue arise array aside asset audio audit avoid awake award aware badly baker bases basic basis beach began begin begun being below bench birth black blame blind block blood board boost booth bound brain brand bread break breed brief bring broad broke brown build built buyer cable carry catch cause chain chair chart chase cheap check chest chief child china chose civil claim class clean clear click clock close coach coast could count court cover craft crash cream crime cross crowd crown curve cycle daily dance dated dealt death debut delay depth doing doubt dozen draft drama drawn dream dress drill drink drive drove dying eager early earth eight elite empty enemy enjoy enter entry equal error event every exact exist extra faith false fault fiber field fifth fifty fight final first fixed flash fleet floor fluid focus force forth forty forum found frame frank fraud fresh front fruit fully funny giant given glass globe going grace grade grand grant grass great green gross group grown guard guess guest guide happy harry heart heavy hence henry horse hotel house human ideal image index inner input issue japan jimmy joint jones judge known label large laser later laugh layer learn lease least leave legal level lewis light limit links lives local logic loose lower lucky lunch lying magic major maker march maria match maybe mayor meant media metal might minor minus mixed model money month moral motor mount mouse mouth movie music needs never newly night noise north noted novel nurse occur ocean offer often order other ought paint panel paper party peace peter phase phone photo piece pilot pitch place plain plane plant plate point pound power press price pride prime print prior prize proof proud prove queen quick quiet quite radio raise range rapid ratio reach ready refer right rival river robin roger roman rough round route royal rural scale scene scope score sense serve seven shall shape share sharp sheet shelf shell shift shirt shock shoot short shown sight since sixth sixty sized skill sleep slide small smart smile smith smoke solid solve sorry sound south space spare speak speed spend spent split spoke sport staff stage stake stand start state steam steel stick still stock stone stood store storm story strip stuck study stuff style sugar suite super sweet table taken taste taxes teach teeth terry texas thank theft their theme there these thick thing think third those three threw throw tight times tired title today topic total touch tough tower track trade train treat trend trial tried tries truck truly trust truth twice under undue union unity until upper upset urban usage usual valid value video virus visit vital voice waste watch water wheel where which while white whole whose woman women world worry worse worst worth would wound write wrong wrote yield young youth'.split(' ');
function wordOfDay() {
  const d = new Date();
  const key = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
  let h = 7;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return WORD_LIST[h % WORD_LIST.length];
}
function scoreGuess(guess, answer) {
  const out = Array(5).fill('absent');
  const left = answer.split('');
  for (let i = 0; i < 5; i++) if (guess[i] === answer[i]) { out[i] = 'correct'; left[i] = null; }
  for (let i = 0; i < 5; i++) {
    if (out[i] === 'correct') continue;
    const at = left.indexOf(guess[i]);
    if (at >= 0) { out[i] = 'present'; left[at] = null; }
  }
  return out;
}
function WordGame({ duelWord, onDuelFinish }) {
  const { theme } = useTheme();
  const [answer, setAnswer] = useState(() => (duelWord ? String(duelWord).toLowerCase() : wordOfDay()));
  const [daily, setDaily] = useState(true);
  const [rows, setRows] = useState([]);
  const [cur, setCur] = useState('');
  const [done, setDone] = useState(null);
  const [shake, setShake] = useState(false);
  const [streak, setStreak] = useState(() => { try { return parseInt(localStorage.getItem('zchat-word-streak') || '0', 10) || 0; } catch { return 0; } });
  const [best, setBest] = useState(() => readBest('word'));
  const saveStreak = (n) => { setStreak(n); try { localStorage.setItem('zchat-word-streak', String(n)); } catch {} if (n > 0) noteSoloScore('word', n); if (n > readBest('word')) { setBest(n); writeBest('word', n); } };
  const colors = { correct: '#22C55E', present: '#EAB308', absent: theme.dark ? '#3A3550' : '#9CA3AF' };
  const keyState = {};
  rows.forEach((r) => r.marks.forEach((mk, i) => { const ch = r.word[i]; const rank = { absent: 1, present: 2, correct: 3 }; if (!keyState[ch] || rank[mk] > rank[keyState[ch]]) keyState[ch] = mk; }));
  const submit = () => {
    if (done) return;
    if (cur.length !== 5) { setShake(true); setTimeout(() => setShake(false), 500); hapticTap(); return; }
    const marks = scoreGuess(cur, answer);
    const next = [...rows, { word: cur, marks }];
    setRows(next);
    setCur('');
    if (cur === answer) { setDone('won'); playUiSound('win'); if (!duelWord) saveStreak(streak + 1); }
    else if (next.length >= 6) { setDone('lost'); playUiSound('lose'); if (!duelWord) saveStreak(0); }
    else playUiSound('toggle');
  };
  const type = (k) => {
    if (done) return;
    if (k === 'enter') { submit(); return; }
    if (k === 'back') { playUiSound('key'); setCur((c) => c.slice(0, -1)); return; }
    if (cur.length < 5) { hapticTap(); playUiSound('key'); setCur((c) => c + k); }
  };
  const newWord = (isDaily) => {
    const w = isDaily ? wordOfDay() : WORD_LIST[Math.floor(Math.random() * WORD_LIST.length)];
    setAnswer(w); setDaily(isDaily); setRows([]); setCur(''); setDone(null);
  };
  useEffect(() => {
    const onKey = (e) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (e.key === 'Enter') { e.preventDefault(); type('enter'); }
      else if (e.key === 'Backspace') { e.preventDefault(); type('back'); }
      else if (/^[a-zA-Z]$/.test(e.key)) { e.preventDefault(); type(e.key.toLowerCase()); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });
  const keyRows = ['qwertyuiop', 'asdfghjkl', 'zxcvbnm'];
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, paddingTop: 6 }}>
      {duelWord ? (
        <GameStats items={[['Tries', rows.length], ['Left', Math.max(0, 6 - rows.length)]]} />
      ) : (
        <GameStats items={[['Streak', streak], ['Best', best]]} right={(
          <button onClick={() => newWord(!daily)} className="zchat-press" style={{ padding: '0 14px', borderRadius: 14, border: 'none', background: theme.rowBg, color: theme.ink, fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer', whiteSpace: 'nowrap' }}>{daily ? 'Random' : 'Daily'}</button>
        )} />
      )}
      <div style={{ fontSize: 12.5, color: theme.muted }}>{duelWord ? 'Your opponent gets the same word. Fewer tries wins.' : daily ? 'Word of the day. Guess it in six tries.' : 'A random word. Guess it in six tries.'}</div>
      <div style={{ display: 'grid', gridTemplateRows: 'repeat(6, 1fr)', gap: 6 }}>
        {Array.from({ length: 6 }).map((_, r) => {
          const row = rows[r];
          const typing = !row && r === rows.length;
          const letters = row ? row.word : (typing ? cur.padEnd(5, ' ') : '     ');
          return (
            <div key={r} className={typing && shake ? 'zchat-shake' : ''} style={{ display: 'grid', gridTemplateColumns: 'repeat(5, var(--zwc, 50px))', gap: 6 }}>
              {letters.split('').map((ch, i) => (
                <div key={i} style={{ width: 'var(--zwc, 50px)', height: 'var(--zwc, 50px)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24, fontWeight: 900, textTransform: 'uppercase', color: row ? 'white' : theme.ink, textShadow: row ? '0 1px 0 rgba(0,0,0,0.25)' : 'none', ...(row ? g3TileStyle(colors[row.marks[i]], 10, 4) : ch.trim() ? g3TileStyle(theme.dark ? '#3B3561' : '#FFFFFF', 10, 4) : { borderRadius: 10, ...g3Hole(theme.dark) }), transition: 'background 0.25s', boxSizing: 'border-box', marginBottom: 4 }}>{ch.trim()}</div>
              ))}
            </div>
          );
        })}
      </div>
      {done && (
        <div style={{ textAlign: 'center', marginTop: 2 }}>
          <div style={{ fontSize: 18, fontWeight: 900, color: theme.ink }}>{done === 'won' ? `Got it in ${rows.length}` : `It was ${answer.toUpperCase()}`}</div>
          {duelWord
            ? <button onClick={() => onDuelFinish && onDuelFinish(done === 'won' ? rows.length : 7)} className="zchat-gbtn" style={{ marginTop: 8, padding: '9px 20px', borderRadius: 14, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Send my result</button>
            : <button onClick={() => newWord(false)} className="zchat-gbtn" style={{ marginTop: 8, padding: '9px 20px', borderRadius: 14, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Next word</button>}
        </div>
      )}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6, alignItems: 'center', width: '100%', maxWidth: 360, marginTop: 4 }}>
        {keyRows.map((kr, ri) => (
          <div key={ri} style={{ display: 'flex', gap: 4, justifyContent: 'center', width: '100%' }}>
            {ri === 2 && <div role="button" aria-label="Enter word" onClick={() => type('enter')} className="zchat-press" style={{ flex: 1.6, height: 44, ...g3TileStyle(theme.dark ? '#4B4478' : '#E4E0F2', 9, 3), color: theme.ink, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 800, cursor: 'pointer', maxWidth: 54, marginBottom: 3 }}>Enter</div>}
            {kr.split('').map((k) => (
              <div key={k} role="button" aria-label={`Key ${k}`} data-silent="1" onClick={() => type(k)} className="zchat-press" style={{ flex: 1, height: 44, ...g3TileStyle(keyState[k] ? colors[keyState[k]] : (theme.dark ? '#3B3561' : '#FFFFFF'), 8, 3), color: keyState[k] ? 'white' : theme.ink, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 15, fontWeight: 800, textTransform: 'uppercase', cursor: 'pointer', maxWidth: 34, userSelect: 'none', marginBottom: 3 }}>{k}</div>
            ))}
            {ri === 2 && <div role="button" aria-label="Delete letter" onClick={() => type('back')} className="zchat-press" style={{ flex: 1.6, height: 44, ...g3TileStyle(theme.dark ? '#4B4478' : '#E4E0F2', 9, 3), color: theme.ink, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', maxWidth: 54, marginBottom: 3 }}><ArrowLeft size={18} /></div>}
          </div>
        ))}
      </div>
    </div>
  );
}

function ReflexGame({ duel, onDuelFinish }) {
  const { theme } = useTheme();
  const [phase, setPhase] = useState('idle');
  const [ms, setMs] = useState(null);
  const [runs, setRuns] = useState([]);
  const [best, setBest] = useState(() => readBest('reflex'));
  const timer = useRef(null);
  const goAt = useRef(0);
  useEffect(() => () => clearTimeout(timer.current), []);
  const arm = () => {
    setPhase('wait'); setMs(null); hapticTap(); playUiSound('key');
    timer.current = setTimeout(() => { goAt.current = performance.now(); setPhase('go'); playUiSound('point'); }, 1200 + Math.random() * 2600);
  };
  const tap = () => {
    if (phase === 'result' && duel) return;
    if (phase === 'idle' || phase === 'result' || phase === 'early') { arm(); return; }
    if (phase === 'wait') { clearTimeout(timer.current); setPhase('early'); playUiSound('cancel'); hapticTap(); return; }
    if (phase === 'go') {
      const t = Math.round(performance.now() - goAt.current);
      setMs(t); setPhase('result'); hapticTap();
      const next = [...runs, t].slice(-5); setRuns(next);
      noteSoloScore('reflex', t);
      const b = readBest('reflex');
      if (!b || t < b) { setBest(t); writeBest('reflex', t); playUiSound('win'); } else playUiSound('like');
    }
  };
  const avg = runs.length ? Math.round(runs.reduce((a, b) => a + b, 0) / runs.length) : null;
  const bg = phase === 'go' ? '#22C55E' : phase === 'wait' ? '#EF4444' : phase === 'early' ? '#F59E0B' : (theme.dark ? '#10335C' : '#1D7BF0');
  const title = phase === 'idle' ? 'Tap to start' : phase === 'wait' ? 'Wait for green' : phase === 'go' ? 'Tap!' : phase === 'early' ? 'Too soon' : `${ms} ms`;
  const text = phase === 'idle' ? 'When the box turns green, tap as fast as you can.' : phase === 'wait' ? 'Hold on' : phase === 'go' ? '' : phase === 'early' ? 'Tap to try again' : (ms < 200 ? 'Lightning fast. Tap to go again' : ms < 300 ? 'Quick. Tap to go again' : 'Tap to go again');
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 14, paddingTop: 8 }}>
      <GameStats items={duel ? [['Your time', ms != null ? `${ms} ms` : '\u2013']] : [['Best', best ? `${best} ms` : '\u2013'], ['Average', avg ? `${avg} ms` : '\u2013'], ['Tries', runs.length]]} />
      <div role="button" aria-label="Reflex pad" data-silent="1" onPointerDown={(e) => { e.preventDefault(); tap(); }} style={{ width: GAME_SQUARE, aspectRatio: '1', borderRadius: 28, background: bg, boxShadow: '0 9px 0 rgba(0,0,0,0.3), inset 0 4px 0 rgba(255,255,255,0.22), inset 0 -10px 24px rgba(0,0,0,0.12)', marginBottom: 9, color: 'white', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 8, cursor: 'pointer', userSelect: 'none', touchAction: 'none', transition: 'background 0.15s', textAlign: 'center', padding: 24, boxSizing: 'border-box' }}>
        <BoltIcon size={44} />
        <div style={{ fontSize: 30, fontWeight: 900 }}>{title}</div>
        <div style={{ fontSize: 14, opacity: 0.85 }}>{duel && phase === 'result' ? 'That is your time for this duel' : text}</div>
      </div>
      {duel && phase === 'result' && ms != null && (
        <button onClick={() => onDuelFinish && onDuelFinish(ms)} className="zchat-gbtn" style={{ padding: '11px 24px', borderRadius: 14, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Send {ms} ms</button>
      )}
      {duel && phase === 'idle' && <div style={{ fontSize: 12.5, color: theme.muted, textAlign: 'center' }}>You get one go. Tap too soon and you can retry.</div>}
    </div>
  );
}

