const ga2Mem = { api: null, job: null, open: null, close: null, setup: null, pending: null, admins: new Map(), me: null, subs: new Set(), db: null };
const GA2_RETIRED = ['ccard'];
function ga2Db() {
  if (!ga2Mem.db) ga2Mem.db = Object.create(supabase, { rpc: { value: (fn, args, opts) => (fn === 'ga2_create' && args && GA2_RETIRED.includes(args.p_kind) ? Promise.resolve({ data: null, error: { code: 'P0001', message: 'ga2:missing' } }) : supabase.rpc(fn, args, opts)) } });
  return ga2Mem.db;
}
function ga2Deps() {
  return {
    React, supabase: ga2Db(), useTheme, FONT, FullPage, Avatar, GameCardShell, GameButton, GameArt, GameInfoButton, Spinner, Portal, useBackClose, useSheetDrag, playUiSound, playSoundboard, hapticTap, appSnack,
    rtKeep, rtName, rtReady, useRtRefresh, reducedMotion, CrownIcon, GAME_TITLES, GAME_ART_BG, g3TileStyle, g3Board, g3dk, g3lt, ConfirmSheet, HeaderIconButton, IgRow, IgToggle, SegmentedControl,
    me: () => ga2Mem.me,
    canHost: (g, uid) => !!g && (g.host_id === uid || (ga2Mem.admins.get(g.group_id) || new Set()).has(uid)),
    openGame: (id) => { if (ga2Mem.open) ga2Mem.open(id); },
    closeGame: (id) => { if (ga2Mem.close) ga2Mem.close(id); },
    setOpener: (o, c, s) => {
      ga2Mem.open = o; ga2Mem.close = c; ga2Mem.setup = s;
      if (s && ga2Mem.pending) { const k = ga2Mem.pending; ga2Mem.pending = null; setTimeout(() => s(k), 0); }
    },
  };
}
function ga2Pack() {
  if (ga2Mem.api) return Promise.resolve(ga2Mem.api);
  if (!ga2Mem.job) {
    ga2Mem.job = cxPack('/games2-pack.js', 'ZGA2').then((ok) => {
      if (ok && window.ZGA2 && !ga2Mem.api) { try { ga2Mem.api = window.ZGA2.install(ga2Deps()); } catch { ga2Mem.api = null; } }
      if (ga2Mem.api) ga2Mem.subs.forEach((f) => { try { f(ga2Mem.api); } catch {} }); else ga2Mem.job = null;
      return ga2Mem.api;
    });
  }
  return ga2Mem.job;
}
function useGa2Api(load) {
  const [api, setApi] = useState(ga2Mem.api);
  useEffect(() => {
    if (api) return undefined;
    const f = (a) => setApi(a);
    ga2Mem.subs.add(f);
    if (load) ga2Pack();
    return () => { ga2Mem.subs.delete(f); };
  }, []);
  return api;
}
function Ga2Card({ state, myId, gid, at }) {
  const api = useGa2Api(true);
  if (api) return <api.Card st={state} myId={myId} gid={gid} at={at} />;
  return <GameCardShell k={state.g} width={252} live title={GAME_TITLES[state.g] || 'Game'} status="Loading"><div style={{ height: 82 }} /></GameCardShell>;
}
function Ga2Bar({ gid, myId }) {
  const api = useGa2Api(false);
  return api ? <api.Bar gid={gid} myId={myId} /> : null;
}
function Ga2Host({ myId, me, group, members, post }) {
  const api = useGa2Api(false);
  const [pick, setPick] = useState(false);
  ga2Mem.me = me;
  useEffect(() => {
    if (!group) return;
    ga2Mem.admins.set(group.id, new Set([group.created_by, ...(members || []).filter((m) => m && m.role === 'admin').map((m) => m.user_id)].filter(Boolean)));
  }, [group, members]);
  useEffect(() => {
    const on = (e) => { if (!group) return; const k = e && e.detail && e.detail.k; if (k && GA2_RETIRED.includes(k)) { appSnack('This game is no longer in ZChat'); return; } if (k && GA2_KEYS.includes(k)) { choose(k); return; } setPick(true); ga2Pack(); };
    window.addEventListener('zchat-ga2-pick', on);
    return () => window.removeEventListener('zchat-ga2-pick', on);
  }, [group]);
  const choose = (k) => {
    setPick(false);
    ga2Mem.pending = k;
    ga2Pack().then((a) => {
      if (!a) { ga2Mem.pending = null; appSnack('Could not load the game. Check your connection and try again'); return; }
      if (ga2Mem.setup && ga2Mem.pending) { const kk = ga2Mem.pending; ga2Mem.pending = null; ga2Mem.setup(kk); }
    });
  };
  return (
    <>
      {pick && group && <Ga2PickerSheet group={group} onClose={() => setPick(false)} onPick={choose} />}
      {api && <api.Host myId={myId} gid={group ? group.id : null} post={post} />}
    </>
  );
}

FRIEND_GAME_GROUPS.unshift(['Play live now', LIVE_GAME_KEYS.filter((k) => k !== 'zombie' || cloudOn())]);
const LIVE_INVITE_MS = 10 * 60 * 1000;

function liveStatusFor(state, myId, peerName) {
  const host = state.x === myId;
  const first = String(peerName || 'They').split(' ')[0];
  if (state.st === 'done') return state.g === 'duo' ? 'Played together' : state.w === 'd' ? 'Draw' : ((state.w === 'x') === host ? 'You won' : `${first} won`);
  if (state.st === 'gone') return 'Game stopped';
  if (state.st === 'live') return 'Playing now';
  if (state.exp && Date.now() > state.exp) return 'Invite ended';
  if (state.g === 'gulpco') return host ? 'Your room is open' : 'Join any time';
  return host ? `Waiting for ${first}` : 'Wants to play now';
}

function LiveGameCard({ state, myId, peerName, onOpen, onRematch }) {
  const { theme } = useTheme();
  const host = state.x === myId;
  const waiting = state.st === 'wait' && (!state.exp || Date.now() <= state.exp);
  useTicker(waiting, 1000);
  const left = state.exp ? Math.max(0, Math.round((state.exp - Date.now()) / 1000)) : 0;
  const first = String(peerName || 'They').split(' ')[0];
  const mine = host ? state.sx || 0 : state.so || 0;
  const theirs = host ? state.so || 0 : state.sx || 0;
  const status = liveStatusFor(state, myId, peerName);
  const hot = waiting && !host;
  const ended = state.st === 'done' || state.st === 'gone' || (state.st === 'wait' && !waiting);
  return (
    <GameCardShell k={state.g} width={236} live title={GAME_TITLES[state.g]} status={status} hot={hot}>
      {state.g === 'race' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>Race in 3D, up to eight friends</div>
      ) : state.g === 'siege' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>Fight robot waves, up to ten friends</div>
      ) : state.g === 'zombie' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>Hold the town against zombies together</div>
      ) : state.g === 'roll' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>Roll together, up to four friends</div>
      ) : state.g === 'gulpco' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>Swim together, up to ten friends</div>
      ) : state.g === 'duo' ? (
        <div style={{ textAlign: 'center', fontSize: 13, fontWeight: 800, color: theme.ink, padding: '2px 0 4px' }}>{state.sx ? `${state.sx} ${state.sx === 1 ? 'level' : 'levels'} cleared together` : 'Escape the temple together'}</div>
      ) : (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, padding: '2px 0 4px' }}>
        <span style={{ fontSize: 12.5, fontWeight: 800, color: theme.muted }}>You</span>
        <span style={{ fontSize: 24, fontWeight: 900, color: theme.ink, fontVariantNumeric: 'tabular-nums' }}>{mine} : {theirs}</span>
        <span style={{ fontSize: 12.5, fontWeight: 800, color: theme.muted, maxWidth: 80, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{first}</span>
      </div>
      )}
      {waiting && state.g !== 'gulpco' && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, fontSize: 12, fontWeight: 700, color: theme.muted, marginTop: 2 }}>
          <span className="zchat-live-dot" style={{ width: 7, height: 7, borderRadius: '50%', background: '#EF4444' }} />
          {`Open for ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}`}
        </div>
      )}
      {state.st === 'live' && <div style={{ textAlign: 'center', fontSize: 12, fontWeight: 700, color: theme.muted }}>A round is happening right now</div>}
      {!ended && <GameAgainButton onClick={onOpen} label={state.g === 'gulpco' ? (host ? 'Open the room' : 'Join the room') : host ? 'Open the game' : 'Join now'} color={host ? 'gold' : 'green'} />}
      {ended && onRematch && <GameAgainButton onClick={onRematch} label={state.st === 'done' && state.g !== 'duo' ? 'Rematch' : 'Play again'} color="green" />}
    </GameCardShell>
  );
}

