    if (mine) { if (legal.some((m) => m[0] === i)) { setSel(sel === i ? null : i); setPromo(null); playUiSound('tap'); } return; }
    if (sel == null) return;
    const opts = legal.filter((m) => m[0] === sel && m[1] === i);
