  const capsBy = (isW) => (st.k || '').split('').filter((ch) => (isW ? ch === ch.toLowerCase() : ch === ch.toUpperCase()));
  const val = (arr) => arr.reduce((a, ch) => a + ((C && C.PIECE_VALUE[ch.toLowerCase()]) || 0), 0);
