                {(white ? c === 0 : c === 7) && <span style={{ position: 'absolute', left: 2, top: 1, fontSize: 7.5, fontWeight: 800, color: dark ? col.l : col.d, opacity: 0.9 }}>{8 - r}</span>}
                {(white ? r === 7 : r === 0) && <span style={{ position: 'absolute', right: 2, bottom: 0, fontSize: 7.5, fontWeight: 800, color: dark ? col.l : col.d, opacity: 0.9 }}>{String.fromCharCode(97 + c)}</span>}
