          {st.dr === myId ? <div style={{ flex: 1, height: 32, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, color: theme.muted }}>Draw offered</div> : <Ga1TextBtn label="Offer draw" onClick={() => { if (canOffer) send({ dr: myId, a: 'offer' }); else appSnack('You can offer a draw right after your move'); }} />}
