const ROOM_WHY = { mate: 'Checkmate', resign: 'Resigned', stale: 'Stalemate', rep: 'Repeated position', fifty: 'Fifty move rule', mat: 'Not enough pieces', agree: 'Draw agreed', kings: 'Only kings moving', time: 'Out of time' };
