function G1Host({ me, myId, messages, peer, group, members, sendDm, sendGroup, openChat, patchMessage, notify, onRematchGame }) {
  const [setup, setSetup] = useState(null);
  const [open, setOpen] = useState(null);
  const [solo, setSolo] = useState(null);
  const [, setPing] = useState(0);
  const want = useRef(null);
  const openRef = useRef(null);
  openRef.current = open;
  const ref = useRef({});
  ref.current = { me, myId, messages, peer, group, members, sendDm, sendGroup, openChat, patchMessage, notify, onRematchGame, openSolo: (lv) => setSolo({ lv, at: Date.now() }) };
  useEffect(() => {
    const api = {
      begin: (profile, kind, gid, opt) => g1Begin(ref.current, profile, kind, setSetup, gid, opt),
      open: (id, how) => { g1LoadFor(ref.current.messages, id); g1Mem.seen.set(id, 1); setOpen({ id, next: null, join: !!(how && how.join) }); },
      openWhenReady: (id) => { want.current = { id, at: Date.now() }; setPing((x) => x + 1); },
      send: (next, opts) => g1HostSend(ref.current, next, opts),
      rematch: (st) => {
        if (!st) return;
        const nid = stableUuid(`next|${st.id}`);
        if (openRef.current && (openRef.current.id === st.id || openRef.current.next === st.id)) setOpen({ id: st.id, next: nid });
        else if (ROOM_GAME_KEYS.includes(st.g) && !ref.current.group) want.current = { id: nid, at: Date.now() };
        if (G1_KEYS.includes(st.g)) g1Rematch(ref.current, st, setSetup);
        else if (ref.current.onRematchGame) ref.current.onRematchGame(st);
      },
      ctx: () => ref.current,
    };
    g1Mem.host = api;
    const f = () => setPing((x) => x + 1);
    g1Mem.subs.add(f);
    return () => { g1Mem.subs.delete(f); if (g1Mem.host === api) g1Mem.host = null; };
  }, []);
  useEffect(() => {
    const names = {};
    if (peer) names[peer.id] = { name: peer.name, avatar: peer.avatar };
    (members || []).forEach((m) => { if (m && m.profile) names[m.user_id] = { name: m.profile.name, avatar: m.profile.avatar }; });
    if (me) names[myId] = { name: me.name, avatar: me.avatar };
    g1Mem.names = names;
    g1Ping();
  }, [peer && peer.id, group && group.id, members, me && me.name, me && me.avatar]);
  useEffect(() => { setOpen(null); }, [peer && peer.id, group && group.id]);
  useEffect(() => {
    const w = want.current;
    if (!w) return;
    if (Date.now() - w.at > 15000) { want.current = null; return; }
    if (g1Latest(messages, w.id) || g1Mem.pending.get(w.id)) { want.current = null; g1LoadFor(messages, w.id); g1Mem.seen.set(w.id, 1); setOpen({ id: w.id, next: null }); }
  });
  useEffect(() => {
    if (!g1Mem.pending.size) return;
    let changed = false;
    g1Mem.pending.forEach((p, id) => {
      if (p === true) return;
      const st = g1Latest(messages, id);
      if (st && (st.n || 0) >= (p.n || 0)) { g1Mem.pending.delete(id); changed = true; }
    });
    if (changed) g1Ping();
  }, [messages]);
  const pick = (id) => {
    if (!id) return null;
    const m = g1Latest(messages, id);
    const p = g1Mem.pending.get(id);
    return p && p !== true && (!m || (p.n || 0) > (m.n || 0)) ? p : m;
  };
  const latest = open ? (pick(open.next) || pick(open.id)) : null;
  const peerName = peer ? String(peer.name || '').split(' ')[0] : '';
  const close = () => setOpen(null);
  const prevOf = (n) => (latest ? g1At(messages, latest.id, n) : null);
  return (
    <>
      {setup && <G1Setup setup={setup} c={ref.current} onClose={() => setSetup(null)} onDone={() => setSetup(null)} />}
      {latest && ROOM_GAME_KEYS.includes(latest.g) && !group && <GameRoomPage key="room" st={latest} prevOf={prevOf} myId={myId} me={me} peer={peer} intent={open && open.join && open.id === latest.id ? 'join' : null} onClose={close} />}
      {latest && latest.g === 'pool' && group && <G1PoolPage st={latest} prevOf={prevOf} myId={myId} peerName={peerName} onClose={close} />}
      {latest && latest.g === 'crm' && group && <CarromPage st={latest} prevOf={prevOf} myId={myId} peerName={peerName} onClose={close} />}
      {latest && latest.g === 'zap' && group && <ZapPage key={latest.id} st={latest} myId={myId} onClose={close} />}
      {latest && latest.g === 'golf' && group && <G1GolfPage st={latest} myId={myId} peerName={peerName} onClose={close} />}
      {latest && latest.g === 'sdk' && <G1SudokuPage key={latest.id} st={latest} myId={myId} peerName={peerName} onClose={close} />}
      {latest && latest.g === 'jig' && <G1JigsawPage key={latest.id} st={latest} myId={myId} peerName={peerName} onClose={close} />}
      {latest && latest.g === 'xw' && <G1CrossPage key={latest.id} st={latest} myId={myId} peerName={peerName} onClose={close} />}
      {solo && <FullPage title="Sudoku" subtitle={G1_LEVELS[solo.lv]} onBack={() => setSolo(null)} zIndex={63} right={<PageCast game="sudoku" room={`sudoku-${String(myId).slice(0, 8)}-${solo.at}`} solo />}><G1SudokuBoard key={solo.at} level={solo.lv} /></FullPage>}
    </>
  );
}
function G1SudokuPage({ st, myId, peerName, onClose }) {
  const { theme } = useTheme();
  const [ask, setAsk] = useState(false);
  const [busy, setBusy] = useState(false);
  useBackClose(true, onClose);
  useBackClose(ask, () => setAsk(false));
  const stRef = useRef(st);
  stRef.current = st;
  const field = myId === st.x ? 'fx' : 'fo';
  const mine = st[field];
  const other = myId === st.x ? st.o : st.x;
  const peer = peerName || g1First(other, 'Them');
  useEffect(() => { if (mine == null) supabase.rpc('zchat_g1_clock_start', { p_game: st.id }).then(() => {}, () => {}); }, []);
  const finish = async (value, tries = 0) => {
    const s = stRef.current;
    if (s[field] != null) return;
    const next = { ...s, n: (s.n || 0) + 1, [field]: value };
    const a = next.fx; const b = next.fo;
    if (a != null && b != null) next.w = a < 0 && b < 0 ? 'd' : a < 0 ? 'o' : b < 0 ? 'x' : a === b ? 'd' : a < b ? 'x' : 'o';
    const ok = await g1Send(next);
    if (!ok && tries < 2) setTimeout(() => finish(value, tries + 1), 1600);
  };
  const solved = async (grid) => {
    setBusy(true);
    let ms = null;
    try {
      const { data, error } = await supabase.rpc('zchat_g1_sudoku_done', { p_game: st.id, p_grid: grid });
      if (!error && data && data.ok) ms = data.ms;
      else if (rpcMissing(error)) ms = null;
    } catch {}
    setBusy(false);
    if (ms == null) { appSnack('Your time could not be checked. Try again in a moment.'); return; }
    finish(ms);
  };
  return (
    <FullPage title="Sudoku race" subtitle={`${G1_LEVELS[st.lv] || ''} with ${peer}`} onBack={onClose} zIndex={63}
      right={<><PageCast game="sdk" room={`sdk-${st.id}-${String(myId).slice(0, 8)}`} />{mine == null && !st.w ? <HeaderIconButton label="Give up" onClick={() => setAsk(true)}><Flag size={19} /></HeaderIconButton> : null}</>}>
      {mine != null ? (
        <div style={{ textAlign: 'center', padding: '40px 10px' }}>
          <div style={{ fontSize: 22, fontWeight: 900, color: theme.ink }}>{mine < 0 ? 'You gave up' : `You finished in ${g1Clock(mine)}`}</div>
          <div style={{ fontSize: 14, color: theme.muted, marginTop: 6 }}>{st.w ? (g1Outcome(st, myId) === 'win' ? 'You were faster' : g1Outcome(st, myId) === 'draw' ? 'It is a draw' : `${peer} was faster`) : `Waiting for ${peer} to finish`}</div>
        </div>
      ) : <G1SudokuBoard givens={st.gv} gameId={st.id} level={st.lv} onSolved={solved} footer={busy ? <div style={{ marginTop: 10 }}><Spinner size={18} color={theme.muted} /></div> : null} />}
      {ask && <ConfirmSheet title="Give up this race" text={`${peer} wins if they finish.`} confirmLabel="Give up" onCancel={() => setAsk(false)} onConfirm={() => { setAsk(false); finish(-1); }} />}
    </FullPage>
  );
}
function G1SoloSudoku() {
  const [lv, setLv] = useState(null);
  const { theme } = useTheme();
  if (!lv) {
    return (
      <div style={{ padding: '18px 4px' }}>
        <div style={{ fontSize: 15, color: theme.muted, lineHeight: 1.5, marginBottom: 14 }}>Pick a level. There is no clock while you play, your time shows when you finish.</div>
        {[1, 2, 3, 4].map((k) => (
          <div key={k} role="button" aria-label={G1_LEVELS[k]} onClick={() => { hapticTap(); setLv(k); }} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '12px 6px', cursor: 'pointer', borderBottom: `1px solid ${theme.hair}` }}>
            <div style={{ width: 40, height: 40, borderRadius: 12, background: GAME_ART_BG.sudoku[0], opacity: 0.35 + k * 0.16, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#FFFFFF', fontWeight: 900, fontSize: 16 }}>{k}</div>
            <div style={{ flex: 1, fontSize: 16, fontWeight: 700, color: theme.ink }}>{G1_LEVELS[k]}</div>
            <ChevronRight size={18} color={theme.muted} />
          </div>
        ))}
      </div>
    );
  }
  return <G1SudokuBoard level={lv} />;
}

function G1JigsawPage({ st, myId, peerName, onClose }) {
  const Z = useG1();
  const { theme } = useTheme();
  const [imgFail, setImgFail] = useState(null);
  const [zFail, setZFail] = useState(false);
  const img = useG1Image(st.u, (retry) => setImgFail(() => retry));
  useEffect(() => {
    if (Z) { setZFail(false); return undefined; }
    const t = setTimeout(() => setZFail(true), 12000);
    return () => clearTimeout(t);
  }, [Z, zFail]);
  const hostRef = useRef(null);
  const [placed, setPlaced] = useState(0);
  const [doneMs, setDoneMs] = useState(st.w === 'done' ? st.tm : null);
  const stRef = useRef(st);
  stRef.current = st;
  useBackClose(true, onClose);
  const solver = myId === st.o;
  const key = `zchat-g1-jig-${st.id}`;
  useEffect(() => {
    if (!Z || !img || !hostRef.current) return undefined;
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(key) || 'null'); } catch {}
    const total = st.pc;
    const done = stRef.current.w === 'done';
    const c = Z.jig.mount(hostRef.current, {
      image: img, pieces: st.pc, seed: st.sd || st.id, ar: st.ar, dark: theme.dark,
      saved: done ? { placed: Array.from({ length: total }, (_, i) => i), ms: st.tm } : saved,
      onPick: () => playUiSound('tap'),
      onSnap: (n) => { setPlaced(n); playUiSound('point'); hapticTap(); },
      onProgress: (p) => { try { localStorage.setItem(key, JSON.stringify(p)); } catch {} },
      onDone: (ms) => {
        setDoneMs(ms);
        playUiSound('win');
        try { window.dispatchEvent(new CustomEvent('zchat-screen-fx', { detail: 'confetti' })); } catch {}
        const s = stRef.current;
        if (solver && s.w !== 'done') g1Send({ ...s, n: (s.n || 0) + 1, w: 'done', tm: ms });
        try { localStorage.removeItem(key); } catch {}
      },
    });
    setPlaced(c.placed());
    if (g1Test()) window.__g1jig = c;
    return () => { c.destroy(); if (window.__g1jig === c) delete window.__g1jig; };
  }, [Z, img]);
  const peer = peerName || g1First(st.x, 'your friend');
  return (
    <FullPage title="Photo jigsaw" subtitle={doneMs != null ? `Solved in ${g1Clock(doneMs)}` : `From ${peer}, ${placed} of ${st.pc} placed`} onBack={onClose} zIndex={63} pad={false}
      right={<PageCast game="jig" room={`jig-${st.id}-${String(myId).slice(0, 8)}`} />}
      bodyStyle={{ display: 'flex', flexDirection: 'column', overflow: 'hidden', paddingBottom: 0 }}>
      <div ref={hostRef} style={{ flex: 1, minHeight: 0, position: 'relative' }}>
        {!img && imgFail && (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 6, padding: '0 28px', textAlign: 'center' }}>
            <LoadFail small onRetry={() => { const r = imgFail; setImgFail(null); r(); }} />
            <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.45 }}>{`Still not loading? Ask ${peer} to send the photo again.`}</div>
          </div>
        )}
        {img && !Z && zFail && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><LoadFail small onRetry={() => { setZFail(false); g1Load(); }} /></div>}
        {(!Z || !img) && !imgFail && !(img && zFail) && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Spinner size={22} color={theme.muted} /></div>}
      </div>
      <div style={{ flexShrink: 0, padding: '8px 16px calc(14px + env(safe-area-inset-bottom))', fontSize: 13.5, color: theme.muted, textAlign: 'center', fontWeight: doneMs != null ? 800 : 600 }}>
        {doneMs != null ? `${peer} sees your time now` : 'Drag a piece close to its spot and it clicks in'}
      </div>
    </FullPage>
  );
}

